content.content:
export interface CoreConcept {
  /** Stable id, used in URLs and saved preferences. */
  id: string;
  name: string;
  /** How it's built — shown as a badge in the gallery. */
  kind: "3D" | "2.5D" | "2D";
  /** One line, shown under the name. */
  tagline: string;
  /** A short paragraph describing the look and how it reacts. */
  description: string;
  /** How it reacts to typing, in one short sentence — shown in the gallery. */
  typing: string;
  /** Canvas half-size relative to the core radius (room for glows/coronas outside the sphere). */
  extent: number;
  /** GLSL defining `vec4 core(vec2 uv)` — premultiplied rgba. Has access to everything in prelude.ts. */
  frag: string;
}
/**
 * Shared GLSL for every core concept: the uniform contract, noise and colour utilities, and the
 * 3D "Y" (a signed-distance field of the vector mark, extruded and ray-marched).
 *
 * A concept supplies `vec4 core(vec2 uv)` returning PREMULTIPLIED rgba for a dark backdrop.
 * `uv` spans -1..1 across a square canvas; the core sphere has radius `uRadius` in those units.
 */

export const PRELUDE = /* glsl */ `
precision highp float;
varying vec2 vUv;

// ── Contract ─────────────────────────────────────────────────────────────
uniform float uTime;     // seconds since the renderer started
uniform float uSwirl;    // accumulated spin: ~0.22 rad/s idle, faster while typing/forging
uniform float uTilt;     // Y sway about the vertical axis (radians, about ±0.5)
uniform float uTiltX;    // Y nod about the horizontal axis (radians, about ±0.13)
uniform float uEnergy;   // 0..1 sustained typing
uniform float uPulse;    // 0..1 heartbeat while Cyrus is thinking / forging
uniform float uKick;     // 0..1 flash on the latest keystroke (decays in ~0.4s)
uniform vec4 uWaveR;     // radii of up to four keystroke shockwaves (sphere units, 0.08 -> ~1.3)
uniform vec4 uWaveS;     // their strengths (0..0.75, fading; 0 = slot unused)
uniform vec4 uWaveAge;   // seconds since each of those keystrokes (0..1.6)
uniform vec4 uWaveSeed;  // a random 0..1 per keystroke — use for impact points, bolt paths, etc.
uniform float uImpulse;  // spring: jolts ~+0.6 on each keystroke, wobbles back to 0 (underdamped)
uniform float uKicks;    // running keystroke count
uniform float uLight;    // 1.0 in light mode
uniform float uRadius;   // core radius in uv units
uniform float uPx;       // one device pixel in uv units (use for anti-aliasing)
uniform float uReady;    // 1.0 once the Y distance field is loaded
uniform float uDPU;
uniform float uSdfK;
uniform vec4 uSdfMap;
uniform vec2 uTexUnits;
uniform sampler2D uSdf;

const float PI = 3.14159265;
const float TAU = 6.2831853;

// ── Noise ────────────────────────────────────────────────────────────────
float hash(vec3 p) { return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453123); }
float hash2(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
vec3 hash33(vec3 p) {
  p = vec3(dot(p, vec3(127.1, 311.7, 74.7)), dot(p, vec3(269.5, 183.3, 246.1)), dot(p, vec3(113.5, 271.9, 124.6)));
  return fract(sin(p) * 43758.5453123);
}
float vnoise(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(mix(hash(i), hash(i + vec3(1, 0, 0)), f.x), mix(hash(i + vec3(0, 1, 0)), hash(i + vec3(1, 1, 0)), f.x), f.y),
    mix(mix(hash(i + vec3(0, 0, 1)), hash(i + vec3(1, 0, 1)), f.x), mix(hash(i + vec3(0, 1, 1)), hash(i + vec3(1, 1, 1)), f.x), f.y),
    f.z);
}
float fbm2(vec3 p) { return 0.62 * vnoise(p) + 0.38 * vnoise(p * 2.07 + 1.7); }
float fbm3(vec3 p) { return 0.53 * vnoise(p) + 0.29 * vnoise(p * 2.03 + 1.7) + 0.18 * vnoise(p * 4.11 + 3.1); }
float fbm4(vec3 p) { return 0.5 * vnoise(p) + 0.25 * vnoise(p * 2.03 + 1.7) + 0.15 * vnoise(p * 4.11 + 3.1) + 0.1 * vnoise(p * 8.2 + 5.3); }
/** Thin bright crests: 1 on the ridges of the noise field, falling off fast. */
float ridged(vec3 p) { return 1.0 - abs(2.0 * fbm3(p) - 1.0); }
/** Distance to the nearest 3D Voronoi border (~0 on the cell walls). */
float cellEdge(vec3 p, float t) {
  vec3 b = floor(p);
  vec3 f = fract(p);
  float d1 = 8.0;
  float d2 = 8.0;
  for (int k = -1; k <= 1; k++)
  for (int j = -1; j <= 1; j++)
  for (int i = -1; i <= 1; i++) {
    vec3 g = vec3(float(i), float(j), float(k));
    vec3 o = hash33(b + g);
    o = 0.5 + 0.42 * sin(t + TAU * o);
    vec3 r = g + o - f;
    float d = dot(r, r);
    if (d < d1) { d2 = d1; d1 = d; } else if (d < d2) { d2 = d; }
  }
  return sqrt(d2) - sqrt(d1);
}

// ── Colour ───────────────────────────────────────────────────────────────
/** Brand spectrum by horizontal position h (-1 left .. 1 right): cyan, blue, violet, magenta, pink. */
vec3 palette(float h) {
  vec3 cyan = vec3(0.10, 0.85, 1.00);
  vec3 blue = vec3(0.22, 0.45, 1.00);
  vec3 violet = vec3(0.55, 0.30, 1.00);
  vec3 magenta = vec3(0.90, 0.22, 0.98);
  vec3 pink = vec3(1.00, 0.27, 0.65);
  vec3 left = mix(blue, cyan, smoothstep(0.35, 1.0, -h));
  vec3 right = mix(magenta, pink, smoothstep(0.35, 1.0, h));
  return mix(violet, h < 0.0 ? left : right, smoothstep(0.0, 0.6, abs(h)));
}
/** Highlight-only, hue-preserving tone map: nothing below 0.72 is touched. */
vec3 tonemap(vec3 col) {
  float m = max(max(col.r, col.g), col.b);
  float tm = m < 0.72 ? m : 0.72 + 0.28 * (1.0 - exp(-(m - 0.72) * 3.6));
  return col * (tm / max(m, 0.0001));
}
/** Sum of the live keystroke shockwaves at radius r, with shell width w. */
float waveField(float r, float w) {
  return uWaveS.x * exp(-pow((r - uWaveR.x) / w, 2.0)) + uWaveS.y * exp(-pow((r - uWaveR.y) / w, 2.0))
       + uWaveS.z * exp(-pow((r - uWaveR.z) / w, 2.0)) + uWaveS.w * exp(-pow((r - uWaveR.w) / w, 2.0));
}

mat3 rotX(float a) { float c = cos(a), s = sin(a); return mat3(1.0, 0.0, 0.0, 0.0, c, s, 0.0, -s, c); }
mat3 rotY(float a) { float c = cos(a), s = sin(a); return mat3(c, 0.0, -s, 0.0, 1.0, 0.0, s, 0.0, c); }
mat3 rotZ(float a) { float c = cos(a), s = sin(a); return mat3(c, s, 0.0, -s, c, 0.0, 0.0, 0.0, 1.0); }

// ── The Y ────────────────────────────────────────────────────────────────
// Local frame: x right, y up, z toward the viewer; the mark is ~1.16 units wide, centred at the
// origin, extruded ±Y_THICK. Its gradients are evaluated analytically (no texture blur).
const float Y_THICK = 0.05;
const float Y_BEVEL = 0.009;

vec3 ySweepCol(vec2 D) {
  vec2 a = vec2(60.0, 540.0);
  vec2 b = vec2(940.0, 60.0);
  float t = clamp(dot(D - a, b - a) / dot(b - a, b - a), 0.0, 1.0);
  vec3 c = mix(vec3(1.0, 0.22, 0.82), vec3(0.925, 0.11, 0.94), smoothstep(0.0, 0.17, t));
  c = mix(c, vec3(0.54, 0.17, 1.0), smoothstep(0.17, 0.38, t));
  c = mix(c, vec3(0.24, 0.36, 1.0), smoothstep(0.38, 0.52, t));
  c = mix(c, vec3(0.32, 0.27, 1.0), smoothstep(0.52, 0.66, t));
  c = mix(c, vec3(0.69, 0.24, 1.0), smoothstep(0.66, 0.84, t));
  return mix(c, vec3(1.0, 0.37, 0.85), smoothstep(0.84, 1.0, t));
}
vec3 yArmCol(vec2 D) {
  vec2 a = vec2(40.0, 60.0);
  vec2 b = vec2(420.0, 290.0);
  float t = clamp(dot(D - a, b - a) / dot(b - a, b - a), 0.0, 1.0);
  vec3 c = mix(vec3(0.27, 0.97, 1.0), vec3(0.09, 0.71, 1.0), smoothstep(0.0, 0.48, t));
  return mix(c, vec3(0.18, 0.34, 1.0), smoothstep(0.48, 1.0, t));
}
/** Design-space point for a local point (the mark's own 1000×600 coordinates). */
vec2 yDesign(vec2 lp) { return vec2(490.0 + lp.x * uDPU, 300.0 - lp.y * uDPU); }
/** Brand colour of the Y at a local point (arm = 1 picks the cyan arm). */
vec3 yColor(vec2 lp, float arm) { return arm > 0.5 ? yArmCol(yDesign(lp)) : ySweepCol(yDesign(lp)); }
/** 2D signed distance to the sweep (x) and arm (y), in local units. Negative inside. */
vec2 ySdf2(vec2 lp) {
  vec2 tc = yDesign(lp) * uSdfMap.xy + uSdfMap.zw;
  vec2 cl = clamp(tc, vec2(0.0), vec2(1.0));
  vec2 v = texture2D(uSdf, cl).rg;
  return (v * 255.0 - 128.0) * uSdfK + length((tc - cl) * uTexUnits);
}
/** 3D signed distance to the extruded, bevelled Y. */
float ySdf3(vec3 p, out float arm) {
  vec2 d = ySdf2(p.xy);
  arm = d.y < d.x ? 1.0 : 0.0;
  vec2 w = vec2(min(d.x, d.y) + Y_BEVEL, abs(p.z) - Y_THICK + Y_BEVEL);
  return min(max(w.x, w.y), 0.0) + length(max(w, 0.0)) - Y_BEVEL;
}
/** World (sphere) space -> the Y's swaying local frame, and back. */
mat3 yToLocal() { return rotX(-uTiltX) * rotY(-uTilt); }
mat3 yToView() { return rotY(uTilt) * rotX(uTiltX); }

/**
 * Ray-march the Y. ro/rd in WORLD space (rd normalised), scale = Y size multiplier (1 = default).
 * Returns the closest distance found (<= ~0 means hit). Outputs the closest local point, its ray
 * distance and which stroke it belongs to. Use yCoverage() for an anti-aliased silhouette.
 */
float yTrace(vec3 ro, vec3 rd, float sMax, float scale, out vec3 pB, out float sB, out float armB) {
  mat3 L = yToLocal();
  vec3 o = L * ro / scale;
  vec3 d = L * rd;
  float minD = 10.0;
  pB = vec3(0.0);
  sB = 1000.0;
  armB = 0.0;
  if (uReady < 0.5) return minD;
  vec3 bmax = vec3(0.64, 0.36, Y_THICK + 0.03);
  vec3 rs = vec3(abs(d.x) < 1e-5 ? 1e-5 : d.x, abs(d.y) < 1e-5 ? 1e-5 : d.y, abs(d.z) < 1e-5 ? 1e-5 : d.z);
  vec3 t0 = (-bmax - o) / rs;
  vec3 t1 = (bmax - o) / rs;
  vec3 tmn = min(t0, t1);
  vec3 tmx = max(t0, t1);
  float tA = max(max(max(tmn.x, tmn.y), tmn.z), 0.0);
  float tB = min(min(min(tmx.x, tmx.y), tmx.z), sMax / scale);
  if (tA >= tB) return minD;
  float s = tA;
  for (int i = 0; i < 80; i++) {
    vec3 p = o + d * s;
    float a;
    float dd = ySdf3(p, a);
    if (dd < minD) { minD = dd; pB = p; sB = s * scale; armB = a; }
    if (dd < 0.0002 || s > tB) break;
    s += max(dd * 0.9, 0.001);
  }
  return minD * scale;
}
/** Anti-aliased coverage from yTrace's closest distance (pxWorld = one pixel in sphere units). */
float yCoverage(float minD, float pxWorld) { return 1.0 - smoothstep(0.0, pxWorld * 1.3, minD); }
/** Surface normal of the Y at a local point (local frame). */
vec3 yNormal(vec3 p) {
  float a;
  float e = 0.0022;
  vec3 g = vec3(ySdf3(p + vec3(e, 0.0, 0.0), a) - ySdf3(p - vec3(e, 0.0, 0.0), a),
                ySdf3(p + vec3(0.0, e, 0.0), a) - ySdf3(p - vec3(0.0, e, 0.0), a),
                ySdf3(p + vec3(0.0, 0.0, e), a) - ySdf3(p - vec3(0.0, 0.0, e), a));
  return g / max(length(g), 1e-6);
}
/**
 * Neon-glass shading for the Y at a traced point. rdWorld = the view ray, emis = glow strength
 * (~1.1 default; raise with uKick/uPulse). Returns colour (not premultiplied).
 */
vec3 yShade(vec3 pB, float armB, vec3 rdWorld, float emis) {
  vec3 nl = yNormal(pB);
  vec3 nv = yToView() * nl;
  vec3 base = yColor(pB.xy, armB);
  vec2 dd = ySdf2(pB.xy);
  float depth2 = -min(dd.x, dd.y);
  float face = abs(nl.z);
  vec3 V = -rdWorld;
  float ndv = clamp(dot(nv, V), 0.0, 1.0);
  vec3 Ld = normalize(vec3(-0.45, 0.75, 0.55));
  float diff = clamp(dot(nv, Ld), 0.0, 1.0);
  float sp = pow(clamp(dot(reflect(-Ld, nv), V), 0.0, 1.0), 42.0);
  float tube = smoothstep(0.004, 0.04, depth2) * face;
  vec3 c = base * emis * (0.8 + 0.3 * diff);
  c = mix(c, mix(base, vec3(1.0), 0.5) * 1.3, tube * (0.24 + uKick * 0.2));
  c += mix(base, vec3(1.0), 0.55) * (1.0 - face) * 0.85;
  c += mix(base, vec3(1.0), 0.35) * pow(1.0 - ndv, 3.0) * 0.45;
  c += vec3(1.0) * sp * 0.85;
  return c;
}
/**
 * The Y as a flat (2D) emblem at screen point p (sphere units), for non-3D concepts.
 * Returns vec4(colour, coverage). Rim-lit from its own distance field, crisp at any size.
 */
vec4 yFlat(vec2 p, float scale, float pxWorld) {
  if (uReady < 0.5) return vec4(0.0);
  vec2 lp = p / scale;
  vec2 d = ySdf2(lp);
  float arm = d.y < d.x ? 1.0 : 0.0;
  float sd = min(d.x, d.y) * scale;
  float cov = 1.0 - smoothstep(-pxWorld * 0.6, pxWorld * 0.6, sd);
  vec3 base = yColor(lp, arm);
  float inner = smoothstep(0.0, 0.035 * scale, -sd);
  vec3 c = mix(mix(base, vec3(1.0), 0.45), base, inner);
  c = mix(c, mix(base, vec3(1.0), 0.4), smoothstep(0.02 * scale, 0.05 * scale, -sd) * 0.35);
  return vec4(c, cov);
}
/** Soft glow around the flat Y (0..1), for halos. */
float yFlatGlow(vec2 p, float scale, float width) {
  if (uReady < 0.5) return 0.0;
  vec2 d = ySdf2(p / scale);
  return exp(-max(min(d.x, d.y) * scale, 0.0) / width);
}

// ── Sphere helpers ───────────────────────────────────────────────────────
/** Front-surface hit of the unit sphere for screen point q (q = uv / uRadius). z = 0 outside. */
vec3 sphereNormal(vec2 q) { return vec3(q, sqrt(max(0.0, 1.0 - dot(q, q)))); }
`;

/** Every concept's shader ends with this. */
export const EPILOGUE = /* glsl */ `
void main() { gl_FragColor = core(vUv); }
`;

import type { CoreConcept } from "../types";

/**
 * Obsidian Nexus — the current core (dark glass, swirling plasma, 3D Y), with the original
 * typing effect: three tilted halo rings orbit outside and spin up as you type, every keystroke
 * sends a ripple rolling outward, and sparks spiral in from the dark and fall into the core.
 */
export const obsidian: CoreConcept = {
  id: "obsidian",
  name: "Obsidian Nexus",
  kind: "3D",
  tagline: "Dark glass, living plasma, orbiting halos",
  description:
    "A refractive obsidian orb with swirling plasma strands around a solid neon Y. Typing brings back the original feel: the outer halos spin up, each keystroke rolls a ripple outward, and sparks spiral in and fall into the core.",
  typing: "Halos spin up, ripples roll outward and sparks spiral into the core.",
  extent: 2.15,
  frag: /* glsl */ `
// Tilted orbit ring around the core, drawn as an ellipse. Returns intensity; front = lower half.
float halo(vec2 P, float a, float squash, float tiltDeg, float spin, float dashN, float dashFill, float satPhase, out float front) {
  float c = cos(radians(-tiltDeg)), s = sin(radians(-tiltDeg));
  vec2 p = vec2(c * P.x - s * P.y, s * P.x + c * P.y);
  vec2 e = vec2(p.x, p.y / squash);
  float L = max(length(e), 1e-4);
  vec2 grad = vec2(p.x / L, p.y / (squash * squash * L));
  float dist = abs(L - a) / max(length(grad), 1e-4);
  float th = atan(e.y, e.x);
  front = step(p.y, 0.0);
  float w = max(0.006, uPx / uRadius * 1.2);
  float line = exp(-pow(dist / w, 2.0));
  float glow = exp(-pow(dist / 0.045, 2.0));
  float dash = dashN > 0.0 ? step(1.0 - dashFill, fract(th / TAU * dashN + spin * 0.6)) : 1.0;
  float sat = pow(0.5 + 0.5 * cos(th - spin * 2.2 + satPhase), 60.0);
  return line * (0.35 * dash + sat * 1.6) + glow * (0.07 + sat * 0.35);
}

vec4 core(vec2 uv) {
  float R = uRadius;
  vec2 P = uv / R;              // sphere units: the orb has radius 1
  float rP = length(P);
  float h = rP > 0.0 ? P.x / rP : 0.0;
  vec3 tint = palette(h);
  float e = uEnergy;
  float t = uTime;
  bool light = uLight > 0.5;
  float pxW = uPx / R;          // one pixel in sphere units
  vec3 col = vec3(0.0);
  float alpha = 0.0;

  // Halo spin: idles slowly, races while typing (uSwirl accumulates faster with energy).
  float spin = uSwirl * 2.4;
  float f1, f2, f3;
  float h1 = halo(P, 1.24, 0.27, -14.0, spin, 70.0, 0.55, 0.0, f1);
  float h2 = halo(P, 1.38, 0.31, 22.0, -spin * 0.8, 0.0, 1.0, 2.1, f2);
  float h3 = halo(P, 1.56, 0.24, -32.0, spin * 1.25, 140.0, 0.35, 4.0, f3);
  vec3 haloCol = vec3(0.45, 0.85, 1.0) * h1 + vec3(0.75, 0.6, 1.0) * h2 + vec3(1.0, 0.5, 0.95) * h3;
  vec3 haloFront = vec3(0.45, 0.85, 1.0) * h1 * f1 + vec3(0.75, 0.6, 1.0) * h2 * f2 + vec3(1.0, 0.5, 0.95) * h3 * f3;
  float haloBoost = 0.55 + e * 0.9 + uPulse * 0.3;

  if (rP < 1.0 + pxW) {
    vec3 n = sphereNormal(P);
    float z = n.z;
    float fresThin = pow(1.0 - z, 5.0);
    float fresSoft = pow(1.0 - z, 2.2);
    vec3 dr = refract(vec3(0.0, 0.0, -1.0), n, 0.82);
    float sExit = max(-2.0 * dot(n, dr), 0.0);
    float sMid = clamp(-dot(n, dr), 0.0, sExit);
    float cd = length(n + dr * sMid);

    vec3 pB; float sB; float armB;
    float minD = yTrace(n, dr, sExit, 1.0, pB, sB, armB);
    float cov = yCoverage(minD, pxW);
    vec3 yCol = vec3(0.0);
    vec3 yBase = vec3(0.0);
    if (minD < 0.03) {
      yBase = yColor(pB.xy, armB);
      yCol = yShade(pB, armB, dr, 1.08 + uPulse * 0.45 + e * 0.3 + uKick * 0.4);
    }
    float yHalo = minD < 0.03 ? exp(-max(minD, 0.0) * 70.0) * (1.0 - cov) : 0.0;

    // Plasma strands in a slow vortex.
    vec3 plFront = vec3(0.0);
    vec3 plBack = vec3(0.0);
    float jit = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
    float sSplit = minD < 0.03 ? sB : 1000.0;
    for (int i = 0; i < 22; i++) {
      float ts = (float(i) + jit) / 22.0 * sExit;
      vec3 p = n + dr * ts;
      float rp = length(p);
      vec3 ps = rotY(uSwirl * (0.5 + 0.7 / (0.3 + rp))) * p;
      float w = fbm2(ps * 2.1 + vec3(0.0, t * 0.05, 0.0));
      float ridge = 1.0 - abs(2.0 * fbm2(ps * 2.6 + vec3(w * 1.8)) - 1.0);
      float fil = pow(smoothstep(0.72, 1.0, ridge), 2.6);
      float heart = exp(-rp * rp * 2.6);
      float dens = fil * (0.12 + 0.88 * heart) * (1.0 + e * 0.6) + heart * 0.012;
      vec3 c = mix(vec3(0.12, 0.72, 1.0), vec3(1.0, 0.28, 0.88), smoothstep(-0.55, 0.55, p.x));
      c = mix(c, vec3(0.62, 0.48, 1.0), heart * 0.55);
      if (ts < sSplit) plFront += c * dens; else plBack += c * dens;
    }
    float stepK = sExit / 22.0 * 1.6;
    plFront *= stepK * mix(1.0, 0.55, cov);
    plBack *= stepK * (1.0 - cov);

    float blocked = cov * step(sB, sMid);
    vec3 heartGlow = (vec3(0.32, 0.26, 1.0) * exp(-cd * cd * 7.0) * 0.26 + vec3(0.75, 0.78, 1.0) * exp(-cd * cd * 34.0) * 0.32)
                   * (0.75 + uPulse * 0.5 + e * 0.6 + uKick * 0.5) * (1.0 - blocked * 0.9);
    vec3 xE = n + dr * sExit;
    float backWall = pow(1.0 - abs(dot(dr, normalize(xE))), 2.4);
    vec3 refl = reflect(vec3(0.0, 0.0, -1.0), n);
    float band = smoothstep(0.55, 0.92, refl.y) * smoothstep(-0.35, 0.25, refl.x + 0.2) * smoothstep(1.0, 0.6, refl.x + 0.2);
    vec3 Lg = normalize(vec3(-0.78, 0.86, 0.42));
    float sd = max(dot(reflect(-Lg, n), vec3(0.0, 0.0, 1.0)), 0.0);
    float spec = pow(sd, 1100.0) * 1.3 + pow(sd, 24.0) * 0.04;
    float caustic = smoothstep(0.62, 0.97, rP) * smoothstep(-0.15, -0.85, P.y) * (1.0 - smoothstep(0.97, 1.0, rP));

    col = mix(vec3(0.03, 0.022, 0.085), vec3(0.006, 0.008, 0.026), smoothstep(0.0, 1.0, rP));
    col += palette(xE.x) * backWall * 0.16 * (1.0 - cov);
    col += heartGlow + plBack;
    col += yBase * yHalo * (0.5 + uPulse * 0.35 + uKick * 0.4);
    col = mix(col, yCol, cov);
    col += plFront;
    col += tint * (fresSoft * 0.2 + fresThin * (1.05 + uPulse * 0.5 + e * 0.35));
    col += mix(tint, vec3(1.0, 0.5, 0.9), 0.35) * caustic * (0.24 + uPulse * 0.2);
    col += vec3(0.75, 0.82, 1.0) * band * 0.13 + vec3(1.0) * spec * 0.9;
    // Halo fronts pass in front of the glass.
    col += haloFront * haloBoost;
    col = tonemap(col);
    float edgeDark = exp(-pow((rP - 0.958) / 0.011, 2.0));
    col *= 1.0 - edgeDark * 0.55;
    col = mix(col, mix(tint, vec3(1.0), 0.35), smoothstep(0.974, 0.995, rP));
    alpha = 1.0 - smoothstep(1.0 - pxW, 1.0 + pxW, rP);
    col *= alpha;
  }

  if (rP > 1.0 - pxW) {
    float d = max(rP - 1.0, 0.0);
    float a = 0.0;
    vec3 c = vec3(0.0);

    // Bloom: brightens while typing.
    float bloom = exp(-d * 43.0) * 0.85 + exp(-d * 10.0) * (0.12 + e * 0.22 + uPulse * 0.12);
    c += tint * bloom;
    a += bloom;

    // Halos outside the glass (both halves).
    c += haloCol * haloBoost;
    a += max(max(haloCol.r, haloCol.g), haloCol.b) * haloBoost;

    // Keystroke ripples rolling outward from the rim.
    for (int k = 0; k < 4; k++) {
      float s = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
      float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
      if (s <= 0.0) continue;
      float rr = 1.02 + ag * 0.75;
      float ring = exp(-pow((rP - rr) / max(0.012, pxW * 1.4), 2.0)) + exp(-pow((rP - rr) / 0.06, 2.0)) * 0.25;
      float f = s * 1.3;
      c += tint * ring * f;
      a += ring * f;
    }

    // Sparks spiralling in from the dark and falling into the core — more as you type.
    for (int i = 0; i < 32; i++) {
      float fi = float(i);
      float period = 1.3 + hash2(vec2(fi, 1.7)) * 1.1;
      float cyc = t / period + hash2(vec2(fi, 4.2));
      float ph = fract(cyc);
      float gen = floor(cyc);
      float live = step(hash2(vec2(fi, gen)), 0.08 + e * 1.1 + uPulse * 0.4);
      if (live < 0.5) continue;
      float a0 = hash2(vec2(gen, fi)) * TAU;
      float dir = hash2(vec2(fi, gen + 3.0)) < 0.5 ? -1.0 : 1.0;
      float r0 = mix(2.0, 1.02, pow(ph, 1.35));
      float ang = a0 + dir * ph * 2.6;
      vec2 head = vec2(cos(ang), sin(ang)) * r0;
      float ph2 = max(ph - 0.05, 0.0);
      float ang2 = a0 + dir * ph2 * 2.6;
      vec2 tail = vec2(cos(ang2), sin(ang2)) * mix(2.0, 1.02, pow(ph2, 1.35));
      vec2 ba = head - tail;
      float hseg = clamp(dot(P - tail, ba) / max(dot(ba, ba), 1e-5), 0.0, 1.0);
      float dseg = length(P - tail - ba * hseg);
      float fade = smoothstep(0.0, 0.15, ph) * (1.0 - smoothstep(0.85, 1.0, ph));
      float spark = exp(-pow(dseg / max(0.008, pxW * 1.2), 2.0)) * (0.3 + 0.7 * hseg) + exp(-pow(length(P - head) / 0.03, 2.0)) * 0.6;
      vec3 sc = mix(vec3(0.4, 0.9, 1.0), vec3(1.0, 0.5, 0.95), hash2(vec2(fi, 9.1)));
      c += sc * spark * fade;
      a += spark * fade;
    }

    a = clamp(a, 0.0, 1.0) * (light ? 0.5 : 1.0);
    c = min(c, vec3(a));
    col += c * (1.0 - alpha);
    alpha += a * (1.0 - alpha);
  }
  return vec4(col, alpha);
}
`,
};
