// Screenshots of a single core concept, rendered bare by /cores?solo=<id>.
// usage: node coreshot.mjs <conceptId> [outPrefix] [--light] [--forge] [--thinking] [--r=170] [--wait=2500]
// Writes <outPrefix>-idle.png, <outPrefix>-typing.png and <outPrefix>-typing2.png (0.6s later),
// each cropped to the core's canvas, and prints any console / shader errors.
import { spawn } from "node:child_process";
import { mkdirSync, rmSync, writeFileSync } from "node:fs";

const args = process.argv.slice(2);
const id = args[0];
if (!id) {
  console.error("usage: node coreshot.mjs <conceptId> [outPrefix] [--light] [--forge] [--thinking] [--r=170] [--wait=2500]");
  process.exit(1);
}
const prefix = args[1] && !args[1].startsWith("--") ? args[1] : `C:/Users/edmem/AppData/Local/Temp/cyrus-shots/core-${id}`;
const flag = (f) => args.includes(f);
const opt = (k, d) => {
  const a = args.find((x) => x.startsWith(`--${k}=`));
  return a ? a.split("=")[1] : d;
};
const light = flag("--light");
const mode = flag("--forge") ? "forging" : flag("--thinking") ? "thinking" : "idle";
const R = Number(opt("r", "170"));
const wait = Number(opt("wait", "2500"));
const W = 1100;
const H = 900;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const port = 9800 + Math.floor(Math.random() * 150);
const profile = `C:/Users/edmem/AppData/Local/Temp/cyrus-shots/prof-core-${port}`;
mkdirSync(profile, { recursive: true });
const chrome = spawn("C:/Program Files/Google/Chrome/Application/chrome.exe", [
  "--headless=new",
  `--remote-debugging-port=${port}`,
  "--hide-scrollbars",
  "--enable-gpu",
  "--ignore-gpu-blocklist",
  `--window-size=${W},${H}`,
  `--user-data-dir=${profile}`,
  "about:blank",
]);
let targets;
for (let i = 0; i < 60; i++) {
  await sleep(250);
  try {
    targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
    if (targets.some((t) => t.type === "page")) break;
  } catch {}
}
const ws = new WebSocket(targets.find((t) => t.type === "page").webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let id_ = 0;
const pending = new Map();
const errors = [];
ws.onmessage = (m) => {
  const msg = JSON.parse(m.data);
  if (msg.method === "Runtime.exceptionThrown") errors.push(msg.params.exceptionDetails.exception?.description?.slice(0, 400));
  if (msg.method === "Runtime.consoleAPICalled" && (msg.params.type === "error" || msg.params.type === "warning"))
    errors.push(msg.params.args.map((a) => a.value ?? a.description).join(" ").slice(0, 2400));
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  }
};
const send = (method, params = {}) =>
  new Promise((r) => {
    const i = ++id_;
    pending.set(i, r);
    ws.send(JSON.stringify({ id: i, method, params }));
  });
const evaluate = async (expr) => (await send("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true })).result?.result?.value;

await send("Runtime.enable");
await send("Emulation.setDeviceMetricsOverride", { width: W, height: H, deviceScaleFactor: 1, mobile: false });

const crop = async (file) => {
  const box = await evaluate(`(()=>{const c=document.querySelector('.core-host canvas');if(!c)return null;const r=c.getBoundingClientRect();return {x:r.x,y:r.y,w:r.width,h:r.height}})()`);
  const clip = box
    ? { x: Math.max(0, box.x), y: Math.max(0, box.y), width: Math.min(W, box.w), height: Math.min(H, box.h), scale: 1 }
    : { x: 0, y: 0, width: W, height: H, scale: 1 };
  const r = await send("Page.captureScreenshot", { format: "png", clip });
  writeFileSync(file, Buffer.from(r.result.data, "base64"));
  console.log("saved", file);
};

const base = `http://localhost:3000/cores?solo=${id}&r=${R}&mode=${mode}${light ? "&light=1" : ""}`;
await send("Page.navigate", { url: base });
await sleep(wait);
const fps = await evaluate(`new Promise(r=>{let n=0;const t0=performance.now();const f=()=>{n++;if(performance.now()-t0<1000)requestAnimationFrame(f);else r(n)};requestAnimationFrame(f)})`);
await crop(`${prefix}-idle.png`);

