/**
 * Imperative effects bus. UI code pokes it; the network's render loop reads it every
 * frame. Keeping this outside React means typing and streaming never re-render the graph.
 */

export type FxEvent =
  | { type: "ripple"; big?: boolean; soft?: boolean }
  | { type: "packets"; path: string[]; count: number; rgb?: string; speed?: number; size?: number; gap?: number }
  | { type: "burst"; id: string; rgb?: string }
  | { type: "flash"; id: string };

type CoreMode = "idle" | "listening" | "thinking" | "forging";

class FxBus {
  /** 0..1, rises with keystrokes / voice, decays over time. */
  energy = 0;
  mode: CoreMode = "idle";
  /** Branch path currently being forged (core → game → category → mod). */
  stream: { path: string[]; rgb: string } | null = null;
  status = "";
  events: FxEvent[] = [];
  /** Launch times of shockwaves inside the core (keystrokes, forge beats). */
  kicks: number[] = [];
  private lastKey = 0;

  /**
   * Typing charges the core from the inside: a small energy bump, and a shockwave that rolls out
   * from the centre through the plasma. Nothing outside the orb reacts to typing.
   */
  keystroke(strength = 1) {
    const now = performance.now();
    this.energy = Math.min(0.7, this.energy + 0.045 * strength);
    if (strength >= 0.3 && now - this.lastKey > 260) {
      this.kick(now);
      this.lastKey = now;
    }
  }

  kick(now = performance.now()) {
    this.kicks.push(now);
    if (this.kicks.length > 8) this.kicks.shift();
  }

  setMode(mode: CoreMode) {
    this.mode = mode;
  }

  startStream(path: string[], rgb: string) {
    this.stream = { path, rgb };
  }

  stopStream() {
    this.stream = null;
  }

  packets(path: string[], count = 3, opts: { rgb?: string; speed?: number; size?: number; gap?: number } = {}) {
    this.events.push({ type: "packets", path, count, ...opts });
  }

  burst(id: string, rgb?: string) {
    this.events.push({ type: "burst", id, rgb });
  }

  ripple(big = false) {
    this.events.push({ type: "ripple", big });
    if (big) this.kick();
  }

  drain(): FxEvent[] {
    const out = this.events;
    this.events = [];
    return out;
  }
}

export const fx = new FxBus();
