import type { CoreConcept } from "../types";

/**
 * Icosa Cage — a neon wireframe icosahedron (with its dual, a dodecahedron, counter-rotating
 * inside) around a glass bead holding the 3D Y. The 30 struts and 12 vertices are projected
 * analytically with perspective; each strut is shaded as a glowing glass tube, depth-sorted
 * two layers deep so front struts occlude back ones. Keystrokes breathe the cage outward and
 * race light along the edges from a seeded vertex, sparking every vertex the front reaches.
 */
export const icosa: CoreConcept = {
  id: "icosa",
  name: "Icosa Cage",
  kind: "3D",
  tagline: "Neon icosahedron, light in its veins",
  description:
    "A perspective neon icosahedron of glass-tube struts, crisp in front and hazy behind, with a counter-rotating dodecahedron and a glass bead cradling the Y. Each keystroke breathes the cage outward and sends light racing edge to edge from a random vertex, sparking every node it reaches.",
  typing: "The cage breathes out and light races edge to edge, sparking each vertex.",
  extent: 1.6,
  frag: /* glsl */ `
const float CAM = 5.0;
const float RING_R = 0.8944272;
const float RING_H = 0.4472136;
const float DOD_RA = 0.6071;
const float DOD_HA = 0.7947;
const float DOD_RB = 0.9822;
const float DOD_HB = 0.1876;
const float RACE_SPEED = 5.2;

// Two nearest opaque fragments (front-to-back), plus additive halo light.
vec3 gC1; vec3 gC2; float gA1; float gA2; float gZ1; float gZ2;
vec3 gGlow; float gGlowA;
vec4 gFront; vec4 gWaveK;
vec3 gS0; vec3 gS1; vec3 gS2; vec3 gS3;
bool gLight;

void pushLayer(vec3 c, float a, float z) {
  if (a < 0.002) return;
  if (z > gZ1) { gC2 = gC1; gA2 = gA1; gZ2 = gZ1; gC1 = c; gA1 = a; gZ1 = z; }
  else if (z > gZ2) { gC2 = c; gA2 = a; gZ2 = z; }
}

vec3 ringPt(float rr, float hh, float k) { float a = k * 1.2566371; return vec3(cos(a) * rr, hh, sin(a) * rr); }
vec3 prj(vec3 w) { float k = CAM / (CAM - w.z); return vec3(w.xy * k, w.z); }
vec3 icoVert(float idx) {
  if (idx < 0.5) return vec3(0.0, 1.0, 0.0);
  if (idx > 10.5) return vec3(0.0, -1.0, 0.0);
  if (idx < 5.5) return ringPt(RING_R, RING_H, idx - 1.0);
  return ringPt(RING_R, -RING_H, idx - 6.0 + 0.5);
}
// Graph distance (in edges) from each wave's source vertex: dot of unit vertices is 1, .447, -.447, -1.
vec4 gdist(vec3 v) {
  vec4 dp = vec4(dot(v, gS0), dot(v, gS1), dot(v, gS2), dot(v, gS3));
  return floor((1.0 - dp) * 1.5 + 0.2);
}
float sparkAt(vec4 gd) {
  vec4 x = gFront - gd;
  return dot(gWaveK, exp(-x * x * 10.0));
}
vec3 inkOf(vec3 c) { return pow(c, vec3(1.35)) * 0.86; }

void strut(vec2 P, vec3 a, vec3 b, vec4 ga, vec4 gb, float w0, float pxW, float hueShift, float bright) {
  vec2 ab = b.xy - a.xy;
  vec2 ap = P - a.xy;
  float L2 = max(dot(ab, ab), 1e-6);
  float h = clamp(dot(ap, ab) / L2, 0.0, 1.0);
  vec2 dv = ap - ab * h;
  float d2 = dot(dv, dv);
  if (d2 > 0.1) return;
  float d = sqrt(d2);
  float z = mix(a.z, b.z, h);
  float kz = CAM / (CAM - z);
  float fr = clamp(z * 0.62 + 0.5, 0.0, 1.0);
  float w = w0 * kz;
  float xw = mix(a.x, b.x, h);
  vec3 hue = palette(clamp(xw * 1.05 * hueShift + z * 0.15, -1.0, 1.0));

  // light racing along the graph from each keystroke's source vertex
  vec4 gd = min(ga + h, gb + 1.0 - h);
  vec4 x = gFront - gd;
  vec4 hd = exp(-x * x * 16.0) + step(0.0, x) * exp(-x * 2.6) * 0.32;
  float race = dot(gWaveK, hd) * bright;

  // tube cross-section
  vec2 nrm = vec2(-ab.y, ab.x) / sqrt(L2);
  float u = clamp(d / w, 0.0, 1.0);
  float s = clamp(dot(dv, nrm) / w, -1.0, 1.0);
  float nz = sqrt(max(1.0 - u * u, 0.0));
  vec3 N = normalize(vec3(nrm * s, nz + 0.05));
  float aa = pxW * 0.85 + (1.0 - fr) * 0.012;
  float cov = 1.0 - smoothstep(w - aa, w + aa, d);
  vec3 Ld = normalize(vec3(-0.5, 0.78, 0.55));
  float sp = pow(max(dot(reflect(-Ld, N), vec3(0.0, 0.0, 1.0)), 0.0), 26.0);
  float coreL = exp(-u * u * 4.0);
  float pulseL = 1.0 + uPulse * 0.55 + uKick * 0.25;

  vec3 c;
  float q = w * w * 3.2;
  float g = q / (d2 + q) * (1.0 - d2 / 0.1);
  if (!gLight) {
    c = hue * (0.22 + 0.95 * coreL) * pulseL + mix(hue, vec3(1.0), 0.78) * pow(coreL, 3.0) * 0.85 * pulseL;
    c += hue * pow(1.0 - nz, 3.0) * 0.35 + vec3(1.0) * sp * 0.65 * fr;
    c *= mix(0.3, 1.0, fr) * bright;
    c += mix(hue, vec3(1.0), 0.62) * race * (0.5 + coreL) * 1.5;
    gGlow += hue * g * (0.22 * mix(0.35, 1.0, fr) * pulseL * bright + race * 0.85);
  } else {
    vec3 ink = inkOf(hue);
    c = ink * (0.62 + 0.38 * coreL) + mix(ink, vec3(1.0), 0.55) * pow(coreL, 4.0) * 0.35;
    c = mix(c, ink * 0.55, pow(1.0 - nz, 2.0) * 0.6) + vec3(1.0) * sp * 0.45 * fr;
    c = mix(vec3(0.97, 0.96, 1.0), c, mix(0.42, 1.0, fr) * bright);
    c = mix(c, mix(hue, vec3(1.0), 0.25), clamp(race, 0.0, 1.0) * 0.8);
    gGlow += hue * g * (0.1 * mix(0.3, 1.0, fr) * bright + race * 0.5);
    gGlowA += g * (0.1 * mix(0.3, 1.0, fr) * bright + race * 0.5);
  }
  pushLayer(c, cov, z);
}

void node(vec2 P, vec3 v, float spark, float r0, float pxW, float hueShift) {
  vec2 dp = P - v.xy;
  float d2 = dot(dp, dp);
  if (d2 > 0.16) return;
  float d = sqrt(d2);
  float z = v.z;
  float kz = CAM / (CAM - z);
  float fr = clamp(z * 0.62 + 0.5, 0.0, 1.0);
  float rr = r0 * kz * (1.0 + spark * 0.35 + uKick * 0.12);
  vec3 hue = palette(clamp(v.x * 1.05 * hueShift + z * 0.15, -1.0, 1.0));
  float aa = pxW * 0.85 + (1.0 - fr) * 0.01;
  float cov = 1.0 - smoothstep(rr - aa, rr + aa, d);
  float u = clamp(d / rr, 0.0, 1.0);
  vec3 N = vec3(dp / rr, sqrt(max(1.0 - u * u, 0.0)));
  vec3 Ld = normalize(vec3(-0.5, 0.78, 0.55));
  float sp = pow(max(dot(reflect(-Ld, N), vec3(0.0, 0.0, 1.0)), 0.0), 40.0);
  float q = rr * rr * 2.5;
  float g = q / (d2 + q) * (1.0 - d2 / 0.16);
  // four-point star flare when the light front hits this vertex
  float fl = spark * (exp(-abs(dp.y) / (pxW * 0.9 + 0.0025)) * exp(-abs(dp.x) / (0.07 + spark * 0.05))
                    + exp(-abs(dp.x) / (pxW * 0.9 + 0.0025)) * exp(-abs(dp.y) / (0.07 + spark * 0.05)));
  vec3 c;
  if (!gLight) {
    c = mix(hue, vec3(1.0), 0.7) * (0.75 + 0.5 * N.z) * (1.0 + uPulse * 0.4) + vec3(1.0) * sp * 0.6;
    c = c * mix(0.32, 1.0, fr) + vec3(1.0) * spark * 1.2;
    gGlow += mix(hue, vec3(1.0), 0.25) * (g * (0.4 * mix(0.3, 1.0, fr) + spark * 1.6) + fl * 1.1);
  } else {
    vec3 ink = inkOf(hue);
    c = ink * (0.7 + 0.3 * N.z) + vec3(1.0) * sp * 0.7;
    c = mix(vec3(0.97, 0.96, 1.0), c, mix(0.45, 1.0, fr));
    c = mix(c, hue, clamp(spark, 0.0, 1.0) * 0.7);
    gGlow += hue * (g * (0.16 + spark * 0.8) + fl * 0.9);
    gGlowA += g * (0.16 + spark * 0.8) + fl * 0.9;
  }
  pushLayer(c, cov, z + 0.03);
}

vec4 core(vec2 uv) {
  float R = uRadius;
  vec2 P = uv / R;
  float rP = length(P);
  float pxW = uPx / R;
  float t = uTime;
  gLight = uLight > 0.5;
  gC1 = vec3(0.0); gC2 = vec3(0.0); gA1 = 0.0; gA2 = 0.0; gZ1 = -9.0; gZ2 = -9.0;
  gGlow = vec3(0.0); gGlowA = 0.0;
  if (rP > 1.6) return vec4(0.0);

  gFront = uWaveAge * RACE_SPEED;
  gWaveK = clamp(uWaveS / 0.75, 0.0, 1.0);
  gS0 = icoVert(floor(uWaveSeed.x * 11.999));
  gS1 = icoVert(floor(uWaveSeed.y * 11.999));
  gS2 = icoVert(floor(uWaveSeed.z * 11.999));
  gS3 = icoVert(floor(uWaveSeed.w * 11.999));

  float breathe = 1.0 + uImpulse * 0.085 + uPulse * 0.03;
  float sc = 0.9 * breathe;
  mat3 M = rotZ(0.16 * sin(t * 0.21)) * rotX(0.46 + 0.1 * sin(t * 0.17)) * rotY(uSwirl * 0.85);
  float sd = 0.5 * (1.0 + uImpulse * 0.14 + uPulse * 0.05);
  mat3 Md = rotZ(-0.2 + 0.1 * sin(t * 0.19 + 1.0)) * rotX(-0.35) * rotY(-uSwirl * 1.35 + 0.5);

  // ── The Y, in a glass bead at the centre ──
  float yS = 0.7;
  vec3 pB; float sB; float armB;
  float minD = yTrace(vec3(P, 3.0), vec3(0.0, 0.0, -1.0), 6.0, yS, pB, sB, armB);
  float yCov = yCoverage(minD, pxW);
  vec3 yBase = vec3(0.0);
  if (minD < 0.04) {
    yBase = yColor(pB.xy, armB);
    vec3 yC = yShade(pB, armB, vec3(0.0, 0.0, -1.0), 1.1 + uPulse * 0.5 + uEnergy * 0.25 + uKick * 0.35);
    if (gLight) yC = mix(yC, yBase * 0.8, 0.25);
    pushLayer(yC, yCov, 3.0 - sB);
  }

  vec4 none = vec4(99.0);
  if (rP < 1.45) {
    vec3 Nw = prj(M * vec3(0.0, sc, 0.0));
    vec3 Sw = prj(M * vec3(0.0, -sc, 0.0));
    vec4 gN = gdist(vec3(0.0, 1.0, 0.0));
    vec4 gS = gdist(vec3(0.0, -1.0, 0.0));
    for (int i = 0; i < 5; i++) {
      float k = float(i);
      vec3 um = ringPt(RING_R, RING_H, k);
      vec3 um1 = ringPt(RING_R, RING_H, k + 1.0);
      vec3 lm = ringPt(RING_R, -RING_H, k + 0.5);
      vec3 lm1 = ringPt(RING_R, -RING_H, k + 1.5);
      vec3 U = prj(M * um * sc);
      vec3 U1 = prj(M * um1 * sc);
      vec3 Lw = prj(M * lm * sc);
      vec3 L1 = prj(M * lm1 * sc);
      vec4 gU = gdist(um);
      vec4 gU1 = gdist(um1);
      vec4 gL = gdist(lm);
      vec4 gL1 = gdist(lm1);
      float w0 = 0.021;
      strut(P, Nw, U, gN, gU, w0, pxW, 1.0, 1.0);
      strut(P, U, U1, gU, gU1, w0, pxW, 1.0, 1.0);
      strut(P, U, Lw, gU, gL, w0, pxW, 1.0, 1.0);
      strut(P, Lw, U1, gL, gU1, w0, pxW, 1.0, 1.0);
      strut(P, Lw, L1, gL, gL1, w0, pxW, 1.0, 1.0);
      strut(P, Lw, Sw, gL, gS, w0, pxW, 1.0, 1.0);
      node(P, U, sparkAt(gU), 0.034, pxW, 1.0);
      node(P, Lw, sparkAt(gL), 0.034, pxW, 1.0);

      // inner dodecahedron (dual), counter-rotating, thinner and cooler
      vec3 A = prj(Md * ringPt(DOD_RA, DOD_HA, k) * sd);
      vec3 A1 = prj(Md * ringPt(DOD_RA, DOD_HA, k + 1.0) * sd);
      vec3 B = prj(Md * ringPt(DOD_RB, DOD_HB, k) * sd);
      vec3 B1 = prj(Md * ringPt(DOD_RB, DOD_HB, k + 1.0) * sd);
      vec3 C = prj(Md * ringPt(DOD_RB, -DOD_HB, k + 0.5) * sd);
      vec3 D = prj(Md * ringPt(DOD_RA, -DOD_HA, k + 0.5) * sd);
      vec3 D1 = prj(Md * ringPt(DOD_RA, -DOD_HA, k + 1.5) * sd);
      float wd = 0.0075;
      strut(P, A, A1, none, none, wd, pxW, -0.8, 0.7);
      strut(P, A, B, none, none, wd, pxW, -0.8, 0.7);
      strut(P, B, C, none, none, wd, pxW, -0.8, 0.7);
      strut(P, C, B1, none, none, wd, pxW, -0.8, 0.7);
      strut(P, C, D, none, none, wd, pxW, -0.8, 0.7);
      strut(P, D, D1, none, none, wd, pxW, -0.8, 0.7);
    }
    node(P, Nw, sparkAt(gN), 0.034, pxW, 1.0);
    node(P, Sw, sparkAt(gS), 0.034, pxW, 1.0);
  }

  // ── Backdrop: inner light and a faint glass bead around the Y ──
  float heart = exp(-rP * rP * 3.2);
  float hb = 0.6 + uPulse * 0.9 + uEnergy * 0.4 + uKick * 0.3;
  vec3 bg;
  float bgA;
  float gr = 0.56;
  float inBead = 1.0 - smoothstep(gr - pxW, gr + pxW, rP);
  vec3 bn = sphereNormal(P / gr);
  float fres = pow(1.0 - bn.z, 3.0) * inBead;
  vec3 Lg = normalize(vec3(-0.6, 0.75, 0.5));
  float bspec = pow(max(dot(reflect(-Lg, bn), vec3(0.0, 0.0, 1.0)), 0.0), 160.0) * inBead;
  float yHalo = minD < 0.04 ? exp(-max(minD, 0.0) * 55.0) * (1.0 - yCov) : 0.0;
  if (!gLight) {
    bg = vec3(0.30, 0.18, 0.85) * heart * 0.22 * hb + vec3(0.6, 0.5, 1.0) * exp(-rP * rP * 14.0) * 0.12 * hb;
    bg += vec3(0.02, 0.015, 0.06) * inBead;
    bg += palette(P.x / gr) * fres * 0.5;
    bg += yBase * yHalo * (0.45 + uPulse * 0.4 + uKick * 0.4);
    bgA = clamp(max(max(bg.r, bg.g), bg.b) + inBead * 0.35, 0.0, 1.0);
  } else {
    bg = mix(vec3(0.62, 0.55, 1.0), vec3(0.85, 0.82, 1.0), 0.5) * 1.0;
    bgA = heart * 0.18 * hb + inBead * 0.12 + fres * 0.35;
    bg = mix(bg, inkOf(palette(P.x / gr)), clamp(fres * 0.35 / max(bgA, 1e-3), 0.0, 1.0));
    bg *= bgA;
    bg += yBase * yHalo * 0.25;
    bgA = clamp(bgA + yHalo * 0.25, 0.0, 1.0);
  }

  // composite: backdrop, then the two nearest fragments, then halos and glass glints
  vec3 col = bg;
  float a = bgA;
  col = col * (1.0 - gA2) + gC2 * gA2;
  a = a * (1.0 - gA2) + gA2;
  col = col * (1.0 - gA1) + gC1 * gA1;
  a = a * (1.0 - gA1) + gA1;
  if (!gLight) {
    col += gGlow;
    col += vec3(1.0) * bspec * 0.9;
    col = tonemap(col);
    a = max(a, max(max(col.r, col.g), col.b));
  } else {
    float ga = clamp(gGlowA, 0.0, 0.85);
    vec3 gcol = gGlow / max(gGlowA, 1e-3);
    col = col + inkOf(gcol) * ga * (1.0 - a);
    a = a + ga * (1.0 - a);
    col += vec3(1.0) * bspec * 0.8 * a;
  }
  float fade = 1.0 - smoothstep(1.25, 1.55, rP);
  col *= fade;
  a = clamp(a * fade, 0.0, 1.0);
  col = clamp(col, 0.0, 1.0);
  col = min(col, vec3(a));
  col += (hash2(gl_FragCoord.xy) - 0.5) / 255.0 * a;
  return vec4(max(col, 0.0), a);
}
`,
};

