import type { CoreConcept } from "../types";

/**
 * Icosa Cage — a neon wireframe icosahedron (with its dual, a dodecahedron, counter-rotating
 * inside) around a glass bead holding the 3D Y. The 30 struts and 12 vertices are projected
 * analytically with perspective; each strut is shaded as a glowing glass tube, depth-sorted
 * two layers deep so front struts occlude back ones. Keystrokes breathe the cage outward and
 * race light along the edges from a seeded vertex, sparking every vertex the front reaches.
 */
export const icosa: CoreConcept = {
  id: "icosa",
  name: "Icosa Cage",
  kind: "3D",
  tagline: "Neon icosahedron, light in its veins",
  description:
    "A perspective neon icosahedron of glass-tube struts, crisp in front and hazy behind, with a counter-rotating dodecahedron and a glass bead cradling the Y. Each keystroke breathes the cage outward and sends light racing edge to edge from a random vertex, sparking every node it reaches.",
  typing: "The cage breathes out and light races edge to edge, sparking each vertex.",
  extent: 1.6,
  frag: /* glsl */ `
const float CAM = 5.0;
const float RING_R = 0.8944272;
const float RING_H = 0.4472136;
const float DOD_RA = 0.6071;
const float DOD_HA = 0.7947;
const float DOD_RB = 0.9822;
const float DOD_HB = 0.1876;
const float RACE_SPEED = 5.2;
const vec2 R72 = vec2(0.30901699, 0.95105652);
const vec2 R36 = vec2(0.80901699, 0.58778525);
const vec2 R108 = vec2(-0.30901699, 0.95105652);

// The two nearest opaque fragments (depth-sorted), plus additive halo light.
vec3 gC1; vec3 gC2; float gA1; float gA2; float gZ1; float gZ2;
vec3 gGlow; float gGlowA;
vec4 gFront; vec4 gWaveK;
vec3 gS0; vec3 gS1; vec3 gS2; vec3 gS3;
bool gLight;

void pushLayer(vec3 c, float a, float z) {
  if (a < 0.002) return;
  if (z > gZ1) { gC2 = gC1; gA2 = gA1; gZ2 = gZ1; gC1 = c; gA1 = a; gZ1 = z; }
  else if (z > gZ2) { gC2 = c; gA2 = a; gZ2 = z; }
}
void over(inout vec3 col, inout float a, vec3 c, float ca) {
  col = col * (1.0 - ca) + c * ca;
  a = a * (1.0 - ca) + ca;
}

vec2 rot2(vec2 v, vec2 cs) { return vec2(v.x * cs.x - v.y * cs.y, v.x * cs.y + v.y * cs.x); }
vec3 ringPt(float rr, float hh, vec2 cs) { return vec3(cs.x * rr, hh, cs.y * rr); }
vec3 prj(vec3 w) { float k = CAM / (CAM - w.z); return vec3(w.xy * k, w.z); }
vec3 icoVert(float idx) {
  if (idx < 0.5) return vec3(0.0, 1.0, 0.0);
  if (idx > 10.5) return vec3(0.0, -1.0, 0.0);
  float k = idx < 5.5 ? idx - 1.0 : idx - 5.5;
  float an = k * 1.2566371;
  return ringPt(RING_R, idx < 5.5 ? RING_H : -RING_H, vec2(cos(an), sin(an)));
}
// Graph distance (in edges) from each wave's source vertex: unit-vertex dots are 1, .447, -.447, -1.
vec4 gdist(vec3 v) {
  vec4 dp = vec4(dot(v, gS0), dot(v, gS1), dot(v, gS2), dot(v, gS3));
  return floor((1.0 - dp) * 1.5 + 0.2);
}
float sparkAt(vec4 gd) {
  vec4 x = gFront - gd;
  return dot(gWaveK, exp(-x * x * 9.0));
}
vec3 inkOf(vec3 c) { return pow(c, vec3(1.4)) * 0.84; }

void strut(vec2 P, vec3 a, vec3 b, vec4 ga, vec4 gb, float w0, float pxW, float hueK, float bright) {
  vec2 ab = b.xy - a.xy;
  vec2 ap = P - a.xy;
  float L2 = max(dot(ab, ab), 1e-6);
  float h = clamp(dot(ap, ab) / L2, 0.0, 1.0);
  vec2 dv = ap - ab * h;
  float d2 = dot(dv, dv);
  if (d2 > 0.05) return;
  float d = sqrt(d2);
  float z = mix(a.z, b.z, h);
  float kz = CAM / (CAM - z);
  float fr = clamp(z * 0.62 + 0.5, 0.0, 1.0);
  float w = w0 * kz;
  vec3 hue = palette(clamp(mix(a.x, b.x, h) * hueK + z * 0.12, -1.0, 1.0));

  // light racing along the graph from each keystroke's source vertex
  vec4 gd = min(ga + h, gb + 1.0 - h);
  vec4 x = gFront - gd;
  vec4 hd = exp(-x * x * 20.0) + step(0.0, x) * exp(-max(x, 0.0) * 2.4) * 0.3;
  float race = dot(gWaveK, hd) * bright;

  // glass tube cross-section
  vec2 nrm = vec2(-ab.y, ab.x) / sqrt(L2);
  float u = clamp(d / w, 0.0, 1.0);
  float s = clamp(dot(dv, nrm) / w, -1.0, 1.0);
  float nz = sqrt(max(1.0 - u * u, 0.0));
  vec3 N = normalize(vec3(nrm * s, nz + 0.05));
  float aa = pxW * 0.85 + (1.0 - fr) * 0.011;
  float cov = 1.0 - smoothstep(w - aa, w + aa, d);
  float sp = pow(max(dot(reflect(vec3(0.5, -0.78, -0.55) * 0.7, N), vec3(0.0, 0.0, 1.0)), 0.0), 24.0);
  float coreL = exp(-u * u * 4.5);
  float pulseL = 1.0 + uPulse * 0.6 + uKick * 0.2;
  float q = w * w * 3.0;
  float g = q / (d2 + q) * (1.0 - d2 / 0.05);

  vec3 c;
  if (!gLight) {
    c = hue * (0.2 + 0.95 * coreL) * pulseL + mix(hue, vec3(1.0), 0.8) * pow(coreL, 3.0) * 0.8 * pulseL;
    c += hue * pow(1.0 - nz, 3.0) * 0.4 + vec3(1.0) * sp * 0.6 * fr;
    c *= mix(0.24, 1.0, fr * fr) * bright;
    c = mix(c, c * vec3(0.7, 0.6, 1.1), (1.0 - fr) * 0.5);
    c += mix(hue, vec3(1.0), 0.65) * race * (0.4 + coreL) * 1.6;
    gGlow += hue * g * (0.2 * mix(0.25, 1.0, fr) * pulseL * bright + race * 0.9);
    pushLayer(c, cov, z);
  } else {
    vec3 ink = inkOf(hue);
    c = ink * (0.7 + 0.3 * coreL) + mix(hue, vec3(1.0), 0.5) * pow(coreL, 6.0) * 0.25;
    c = mix(c, ink * 0.55, pow(1.0 - nz, 2.0) * 0.7) + vec3(1.0) * sp * 0.4 * fr;
    c = mix(c, mix(hue, vec3(1.0), 0.15), clamp(race, 0.0, 1.0) * 0.85);
    float gl = g * (0.07 * mix(0.3, 1.0, fr) * bright + race * 0.45);
    gGlow += hue * gl;
    gGlowA += gl;
    pushLayer(c, cov * mix(0.3, 1.0, fr) * bright, z);
  }
}

void node(vec2 P, vec3 v, float spark, float r0, float pxW) {
  vec2 dp = P - v.xy;
  float d2 = dot(dp, dp);
  if (d2 > 0.12) return;
  float d = sqrt(d2);
  float z = v.z;
  float kz = CAM / (CAM - z);
  float fr = clamp(z * 0.62 + 0.5, 0.0, 1.0);
  float rr = r0 * kz * (1.0 + spark * 0.3 + uKick * 0.1);
  vec3 hue = palette(clamp(v.x + z * 0.12, -1.0, 1.0));
  float aa = pxW * 0.85 + (1.0 - fr) * 0.01;
  float cov = 1.0 - smoothstep(rr - aa, rr + aa, d);
  float u = clamp(d / rr, 0.0, 1.0);
  vec3 N = vec3(dp / rr, sqrt(max(1.0 - u * u, 0.0)));
  float sp = pow(max(dot(reflect(vec3(0.5, -0.78, -0.55) * 0.7, N), vec3(0.0, 0.0, 1.0)), 0.0), 40.0);
  float q = rr * rr * 2.2;
  float g = q / (d2 + q) * (1.0 - d2 / 0.12);
  // four-point star flare when the light front reaches this vertex
  float thin = pxW * 0.9 + 0.002;
  float reach = 0.05 + spark * 0.09;
  float fl = spark * (exp(-abs(dp.y) / thin - abs(dp.x) / reach) + exp(-abs(dp.x) / thin - abs(dp.y) / reach));
  vec3 c;
  if (!gLight) {
    c = mix(hue, vec3(1.0), 0.72) * (0.7 + 0.5 * N.z) * (1.0 + uPulse * 0.45) + vec3(1.0) * sp * 0.6;
    c = c * mix(0.26, 1.0, fr * fr) + vec3(1.0) * spark * 1.3;
    gGlow += mix(hue, vec3(1.0), 0.3) * (g * (0.38 * mix(0.25, 1.0, fr) * (1.0 + uPulse * 0.6) + spark * 1.8) + fl * 1.2);
    pushLayer(c, cov, z + 0.03);
  } else {
    vec3 ink = inkOf(hue);
    c = ink * (0.72 + 0.28 * N.z) + vec3(1.0) * sp * 0.75;
    c = mix(c, mix(hue, vec3(1.0), 0.2), clamp(spark, 0.0, 1.0) * 0.8);
    float gl = g * (0.1 + spark * 0.6) + fl * 0.8;
    gGlow += hue * gl;
    gGlowA += gl;
    pushLayer(c, cov * mix(0.35, 1.0, fr), z + 0.03);
  }
}

vec4 core(vec2 uv) {
  float R = uRadius;
  vec2 P = uv / R;
  float rP = length(P);
  float pxW = uPx / R;
  float t = uTime;
  gLight = uLight > 0.5;
  gC1 = vec3(0.0); gC2 = vec3(0.0); gA1 = 0.0; gA2 = 0.0; gZ1 = -9.0; gZ2 = -9.0;
  gGlow = vec3(0.0); gGlowA = 0.0;
  if (rP > 1.6) return vec4(0.0);

  gFront = uWaveAge * RACE_SPEED;
  gWaveK = clamp(uWaveS / 0.75, 0.0, 1.0);
  gS0 = icoVert(floor(uWaveSeed.x * 11.999));
  gS1 = icoVert(floor(uWaveSeed.y * 11.999));
  gS2 = icoVert(floor(uWaveSeed.z * 11.999));
  gS3 = icoVert(floor(uWaveSeed.w * 11.999));

  float breathe = 1.0 + uImpulse * 0.085 + uPulse * 0.03;
  float sc = 0.9 * breathe;
  mat3 M = rotZ(0.16 * sin(t * 0.21)) * rotX(0.46 + 0.1 * sin(t * 0.17)) * rotY(uSwirl * 0.85);
  float sd = 0.5 * (1.0 + uImpulse * 0.14 + uPulse * 0.05);
  mat3 Md = rotZ(-0.2 + 0.1 * sin(t * 0.19 + 1.0)) * rotX(-0.35) * rotY(-uSwirl * 1.35 + 0.5);

  // ── The Y, floating in a glass bead at the centre ──
  float yS = 0.8;
  vec3 pB; float sB; float armB;
  float minD = yTrace(vec3(P, 3.0), vec3(0.0, 0.0, -1.0), 6.0, yS, pB, sB, armB);
  float yCov = yCoverage(minD, pxW);
  vec3 yBase = vec3(0.0);
  vec3 yC = vec3(0.0);
  float zY = -99.0;
  if (minD < 0.04) {
    yBase = yColor(pB.xy, armB);
    yC = yShade(pB, armB, vec3(0.0, 0.0, -1.0), 1.1 + uPulse * 0.5 + uEnergy * 0.25 + uKick * 0.35);
    if (gLight) yC = mix(yC, yBase * 0.85, 0.2);
    if (yCov > 0.0) zY = 3.0 - sB;
  }

  if (rP < 1.4) {
    vec3 Nw = prj(M * vec3(0.0, sc, 0.0));
    vec3 Sw = prj(M * vec3(0.0, -sc, 0.0));
    vec4 gN = gdist(vec3(0.0, 1.0, 0.0));
    vec4 gS = gdist(vec3(0.0, -1.0, 0.0));
    vec4 none = vec4(99.0);
    for (int i = 0; i < 5; i++) {
      float an = float(i) * 1.2566371;
      vec2 c0 = vec2(cos(an), sin(an));
      vec2 c1 = rot2(c0, R72);
      vec2 cL = rot2(c0, R36);
      vec2 cL1 = rot2(c0, R108);
      // icosahedron sector: pole, upper ring, lower ring
      vec3 um = ringPt(RING_R, RING_H, c0);
      vec3 um1 = ringPt(RING_R, RING_H, c1);
      vec3 lm = ringPt(RING_R, -RING_H, cL);
      vec3 lm1 = ringPt(RING_R, -RING_H, cL1);
      vec3 U = prj(M * um * sc);
      vec3 U1 = prj(M * um1 * sc);
      vec3 Lw = prj(M * lm * sc);
      vec3 L1 = prj(M * lm1 * sc);
      vec4 gU = gdist(um);
      vec4 gU1 = gdist(um1);
      vec4 gL = gdist(lm);
      vec4 gL1 = gdist(lm1);
      // dodecahedron sector (the dual), counter-rotating
