  if (rP < 1.4) {
    vec3 Nw = prj(M * vec3(0.0, sc, 0.0));
    vec3 Sw = prj(M * vec3(0.0, -sc, 0.0));
    vec4 gN = gdist(vec3(0.0, 1.0, 0.0));
    vec4 gS = gdist(vec3(0.0, -1.0, 0.0));
    vec4 none = vec4(99.0);
    for (int i = 0; i < 5; i++) {
      float an = float(i) * 1.2566371;
      vec2 c0 = vec2(cos(an), sin(an));
      vec2 c1 = rot2(c0, R72);
      vec2 cL = rot2(c0, R36);
      vec2 cL1 = rot2(c0, R108);
