      vec3 A1 = prj(Md * ringPt(DOD_RA, DOD_HA, c1) * sd);
      vec3 B = prj(Md * ringPt(DOD_RB, DOD_HB, c0) * sd);
      vec3 B1 = prj(Md * ringPt(DOD_RB, DOD_HB, c1) * sd);
      vec3 C = prj(Md * ringPt(DOD_RB, -DOD_HB, cL) * sd);
      vec3 D = prj(Md * ringPt(DOD_RA, -DOD_HA, cL) * sd);
      vec3 D1 = prj(Md * ringPt(DOD_RA, -DOD_HA, cL1) * sd);
      for (int j = 0; j < 12; j++) {
