        else if (j == 2) { a = U; b = Lw; ga = gU; gb = gL; }
        else if (j == 3) { a = Lw; b = U1; ga = gL; gb = gU1; }
        else if (j == 4) { a = Lw; b = L1; ga = gL; gb = gL1; }
        else if (j == 5) { a = Lw; b = Sw; ga = gL; gb = gS; }
        else if (j == 6) { a = A; b = A1; ga = none; gb = none; }
        else if (j == 7) { a = A; b = B; ga = none; gb = none; }
        else if (j == 8) { a = B; b = C; ga = none; gb = none; }
        else if (j == 9) { a = C; b = B1; ga = none; gb = none; }
        else if (j == 10) { a = C; b = D; ga = none; gb = none; }
        else if (j == 11) { a = D; b = D1; ga = none; gb = none; }
        bool inner = j > 5;
        strut(P, a, b, ga, gb, inner ? 0.0072 : 0.021, pxW, inner ? -0.85 : 1.0, inner ? 0.75 : 1.0);
      }
    }
    for (int i = 0; i < 12; i++) {
      vec3 vm = icoVert(float(i));
      node(P, prj(M * vm * sc), sparkAt(gdist(vm)), 0.033, pxW);
    }
  }

  // ── Spark bursts thrown off each keystroke's source vertex ──
  vec3 burst = vec3(0.0);
  for (int k = 0; k < 4; k++) {
    float s = k == 0 ? gWaveK.x : k == 1 ? gWaveK.y : k == 2 ? gWaveK.z : gWaveK.w;
    float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
    vec3 sv = k == 0 ? gS0 : k == 1 ? gS1 : k == 2 ? gS2 : gS3;
    float sdd = k == 0 ? uWaveSeed.x : k == 1 ? uWaveSeed.y : k == 2 ? uWaveSeed.z : uWaveSeed.w;
    if (s <= 0.0 || ag > 0.7) continue;
    vec3 sp = prj(M * sv * sc);
    vec2 dp = P - sp.xy;
    if (dot(dp, dp) > 0.25) continue;
    vec2 outD = normalize(sp.xy + vec2(1e-4));
    for (int i = 0; i < 7; i++) {
      float fi = float(i);
      float hs = hash2(vec2(fi, sdd * 91.0));
      float an = atan(outD.y, outD.x) + (fi / 7.0 - 0.5) * 2.6 + (hs - 0.5) * 0.5;
      vec2 dir = vec2(cos(an), sin(an));
      float sp0 = 0.35 + hash2(vec2(sdd * 37.0, fi)) * 0.45;
      float tr = sp0 * (1.0 - exp(-ag * 5.0)) / 5.0 * 4.0;
      vec2 head = dir * tr;
      vec2 tail = dir * max(tr - 0.06, 0.0);
      vec2 ba = head - tail;
      float hh = clamp(dot(dp - tail, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
      float dd = length(dp - tail - ba * hh);
      float fade = exp(-ag * 5.5) * s;
      burst += mix(palette(clamp(sp.x, -1.0, 1.0)), vec3(1.0), 0.6) * exp(-dd * dd / (pxW * pxW * 2.0 + 0.00002)) * hh * fade * 1.4;
    }
  }

  // ── Backdrop: inner light and a clear glass bead around the Y ──
  float heart = exp(-rP * rP * 3.0);
  float hb = 0.6 + uPulse * 1.0 + uEnergy * 0.4 + uKick * 0.3;
  float gr = 0.66;
  float inBead = 1.0 - smoothstep(gr - pxW, gr + pxW, rP);
  vec3 bn = sphereNormal(P / gr);
  float zB = rP < gr ? bn.z * gr : -99.0;
  float fres = pow(1.0 - bn.z, 4.0) * inBead;
  vec3 Lg = normalize(vec3(-0.6, 0.75, 0.5));
  float bspec = pow(max(dot(reflect(-Lg, bn), vec3(0.0, 0.0, 1.0)), 0.0), 220.0) * inBead;
  vec3 brefl = reflect(vec3(0.0, 0.0, -1.0), bn);
  float band = smoothstep(0.5, 0.9, brefl.y) * smoothstep(-0.5, 0.1, brefl.x) * smoothstep(0.8, 0.3, brefl.x) * inBead;
  float rimLine = exp(-pow((rP - gr * 0.985) / (pxW * 1.2 + 0.002), 2.0));
  float yHalo = minD < 0.04 ? exp(-max(minD, 0.0) * 50.0) * (1.0 - yCov) : 0.0;
  vec3 col;
  float a;
  vec3 beadAdd;
  if (!gLight) {
    col = vec3(0.32, 0.2, 0.9) * heart * 0.2 * hb + vec3(0.62, 0.5, 1.0) * exp(-rP * rP * 12.0) * 0.12 * hb;
    col += vec3(0.012, 0.01, 0.04) * inBead;
    col += yBase * yHalo * (0.5 + uPulse * 0.4 + uKick * 0.5);
    a = clamp(max(max(col.r, col.g), col.b) * 1.2 + inBead * 0.25, 0.0, 1.0);
    beadAdd = palette(P.x / gr) * (fres * 0.55 + rimLine * 0.18) + vec3(0.8, 0.85, 1.0) * band * 0.07 + vec3(1.0) * bspec * 0.9;
  } else {
    a = clamp(heart * 0.1 * hb + inBead * 0.06 + yHalo * 0.3, 0.0, 1.0);
    col = (vec3(0.58, 0.5, 0.98) * (heart * 0.1 * hb + inBead * 0.06) + inkOf(yBase) * yHalo * 0.3);
    beadAdd = vec3(0.0);
  }

  // composite: [layers behind the Y] Y [layers inside the bead] bead [layers in front]
  // front struts are glassy where they pass over the Y so the mark always reads.
  float glassK = 1.0 - 0.55 * yCov;
  if (gZ2 < zY) over(col, a, gC2, gA2);
  if (gZ1 < zY) over(col, a, gC1, gA1);
  over(col, a, yC, yCov);
  if (gZ2 >= zY && gZ2 < zB) over(col, a, gC2, gA2 * glassK);
  if (gZ1 >= zY && gZ1 < zB) over(col, a, gC1, gA1 * glassK);
  if (!gLight) {
    col += beadAdd;
  } else {
    float ba = clamp(fres * 0.4 + rimLine * 0.25, 0.0, 1.0);
    over(col, a, inkOf(palette(P.x / gr)) * 0.9, ba);
    col = mix(col, vec3(a), bspec * 0.9);
  }
  if (gZ2 >= zB && gZ2 >= zY) over(col, a, gC2, gA2 * glassK);
  if (gZ1 >= zB && gZ1 >= zY) over(col, a, gC1, gA1 * glassK);

  if (!gLight) {
    col += gGlow + burst;
    col = tonemap(col);
    a = max(a, max(max(col.r, col.g), col.b));
  } else {
    float ga = clamp(gGlowA, 0.0, 0.8);
    vec3 gcol = gGlow / max(gGlowA, 1e-3);
    col += mix(gcol, inkOf(gcol), 0.5) * ga * (1.0 - a);
    a += ga * (1.0 - a);
    float bl = clamp(max(max(burst.r, burst.g), burst.b), 0.0, 1.0);
    over(col, a, inkOf(burst / max(bl, 1e-3)), bl * 0.9);
  }
  float fade = 1.0 - smoothstep(1.25, 1.55, rP);
  a = clamp(a * fade, 0.0, 1.0);
  col = min(max(col * fade, 0.0), vec3(a));
  col += (hash2(gl_FragCoord.xy) - 0.5) / 255.0 * a;
  return vec4(max(col, 0.0), a);
}
`,
};

