import type { CoreConcept } from "../types";

/**
 * Organic Lattice — a ceramic sphere shell cut by a slowly warping gyroid, ray-marched (front
 * shell, then the back shell seen from inside). The hollow holds a blue-violet light and the 3D
 * Y. Light escaping through the holes is integrated volumetrically outside the sphere, so the
 * god-rays are the true radial projection of the openings. Typing dilates the holes and fires
 * pulses of light out through them.
 */
export const lattice: CoreConcept = {
  id: "lattice",
  name: "Organic Lattice",
  kind: "3D",
  tagline: "Ceramic shell, light within",
  description:
    "A pearl-white ceramic lattice, grown like coral, cradling a blue-violet light and the glowing Y in its hollow. Typing dilates the openings and every keystroke fires a pulse of light out through them, throwing god-rays past the shell.",
  typing: "The lattice opens up and each keystroke bursts light out through its holes.",
  extent: 1.9,
  frag: /* glsl */ `
const float RM = 0.86;
const float TH = 0.082;
mat3 gR;
float gK;
float gT;

float smaxK(float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (a - b) / k, 0.0, 1.0);
  return mix(b, a, h) + k * h * (1.0 - h);
}
float gyro(vec3 p) { return dot(sin(p), cos(p.yzx)); }
float latG(vec3 p) {
  vec3 q = gR * p;
  q += 0.055 * sin(q.zxy * 3.6 + uTime * 0.21);
  return gyro(q * gK);
}
float latSdf(vec3 p) {
  float ds = abs(length(p) - RM) - TH;
  float dg = (abs(latG(p)) - gT) / (gK * 1.55);
  return smaxK(ds, dg, 0.045);
}
vec3 latNormal(vec3 p) {
  vec2 e = vec2(0.0028, -0.0028);
  vec3 n = e.xyy * latSdf(p + e.xyy) + e.yyx * latSdf(p + e.yyx) + e.yxy * latSdf(p + e.yxy) + e.xxx * latSdf(p + e.xxx);
  return n / max(length(n), 1e-6);
}
// Interior light colour by distance from the heart.
vec3 innerCol(float rho) {
  return mix(vec3(0.62, 0.4, 1.0), vec3(0.14, 0.32, 1.0), smoothstep(0.05, 0.75, rho));
}
// Keystroke pulse radii (my own fast expansion) and strengths.
vec4 pulseR() { return uWaveAge * 2.7; }
vec4 pulseS() { return step(0.001, uWaveS) * exp(-uWaveAge * 3.2); }
float pulseAt(float rho, float w) {
  vec4 x = (rho - pulseR()) / w;
  return dot(pulseS(), exp(-x * x));
}

vec4 core(vec2 uv) {
  float R = uRadius;
  vec2 P = uv / R;
  float rP = length(P);
  float r2 = dot(P, P);
  float pxW = uPx / R;
  float t = uTime;
  bool light = uLight > 0.5;
  float e = uEnergy;
  if (rP > 1.9) return vec4(0.0);

  gR = rotZ(0.25) * rotX(0.35 + 0.08 * sin(t * 0.13)) * rotY(uSwirl * 0.42);
  gK = 6.4;
  gT = 0.66 * (1.0 - 0.34 * e - 0.12 * uPulse) * (1.0 - 0.16 * uImpulse);

  float Ro = RM + TH + 0.012;
  float Ri = RM - TH - 0.012;
  float heartI = 0.75 + uPulse * 0.8 + e * 0.55 + uKick * 0.5;
  float shellPulse = pulseAt(RM, 0.22);
  vec3 L = normalize(vec3(-0.52, 0.68, 0.52));
  vec3 V = vec3(0.0, 0.0, 1.0);
  float jit = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));

  vec3 col = vec3(0.0);
  float a = 0.0;

  if (rP < Ro + pxW * 2.0) {
    float zo = sqrt(max(Ro * Ro - r2, 0.0));
    bool inner = rP < Ri;
    float zin = inner ? sqrt(Ri * Ri - r2) : 0.0;
    float zEnd = inner ? zin : -zo;

    // ── front shell ──
    float s = 0.0;
    float minD = 9.0;
    vec3 pMin = vec3(P, zo);
    for (int i = 0; i < 44; i++) {
      vec3 p = vec3(P, zo - s);
      float d = latSdf(p);
      if (d < minD) { minD = d; pMin = p; }
      if (d < 0.0006) break;
      s += max(d * 0.82, 0.0025);
      if (zo - s < zEnd - 0.01) break;
    }
    float cov = 1.0 - smoothstep(0.0, pxW * 1.5, minD);

    // ── what lies behind the front shell ──
    vec3 bc = vec3(0.0);
    float ba = 0.0;
    vec3 yBase = vec3(0.0);
    if (cov < 0.999) {
      if (inner) {
        // back shell, seen from inside, lit by the heart
        float s2 = 0.0;
        float minD2 = 9.0;
        vec3 q2 = vec3(P, -zin);
        for (int i = 0; i < 26; i++) {
          vec3 p = vec3(P, -zin - s2);
          float d = latSdf(p);
          if (d < minD2) { minD2 = d; q2 = p; }
          if (d < 0.0008) break;
          s2 += max(d * 0.85, 0.003);
          if (-zin - s2 < -zo - 0.01) break;
        }
        float cov2 = 1.0 - smoothstep(0.0, pxW * 2.0, minD2);
        vec3 nb = latNormal(q2);
        float rb = length(q2);
        float toHeart = clamp(dot(nb, -q2 / max(rb, 1e-4)), 0.0, 1.0);
        vec3 backLit = innerCol(0.8) * (0.28 + 0.72 * toHeart) * (0.55 + 0.45 * heartI) + innerCol(0.3) * shellPulse * 0.9;
        backLit *= 0.95;
        // the deep hollow behind, seen through a back opening
        float chord = 2.0 * zin;
        vec3 deep = mix(vec3(0.05, 0.06, 0.28), vec3(0.2, 0.22, 0.75), exp(-r2 * 2.0)) * (0.6 + 0.4 * heartI);
        float deepA = 1.0 - exp(-chord * 2.6);
        bc = deep * deepA;
        ba = deepA;
        bc = bc * (1.0 - cov2) + backLit * cov2;
        ba = ba * (1.0 - cov2) + cov2;

        // volumetric heart light along the chord (gaussian line integral) plus keystroke pulses
        float vol = exp(-r2 * 2.4) * (0.32 + 0.3 * heartI);
        float core0 = exp(-r2 * 14.0) * 0.4 * heartI;
        float pr = pulseAt(rP, 0.13) * 1.2 + pulseAt(rP, 0.45) * 0.35;
        vec3 glow = innerCol(rP) * vol + vec3(0.75, 0.7, 1.0) * core0 + mix(innerCol(rP), vec3(1.0), 0.45) * pr;

        // the Y, glowing in the hollow
        vec3 pB; float sB; float armB;
        float yS = 0.78;
        float yD = yTrace(vec3(P, 3.0), vec3(0.0, 0.0, -1.0), 6.0, yS, pB, sB, armB);
        float yCov = yCoverage(yD, pxW);
        float yHalo = 0.0;
        if (yD < 0.05) {
          yBase = yColor(pB.xy, armB);
          vec3 yC = yShade(pB, armB, vec3(0.0, 0.0, -1.0), 1.15 + uPulse * 0.5 + e * 0.3 + uKick * 0.45);
          yHalo = exp(-max(yD, 0.0) * 45.0) * (1.0 - yCov);
          bc = mix(bc, yC, yCov);
          ba = mix(ba, 1.0, yCov);
        }
        bc += glow * (1.0 - yCov * 0.7) + yBase * yHalo * (0.55 + uPulse * 0.4 + uKick * 0.5);
        ba = clamp(ba + max(max(glow.r, glow.g), glow.b), 0.0, 1.0);
      } else {
        // grazing through the rim: only a little light leaks here
        vec3 glow = innerCol(0.9) * 0.1 * heartI;
        bc = glow;
        ba = 0.1;
      }
    }

    // ── shade the front (outer) surface: pearl ceramic ──
    vec3 fc = vec3(0.0);
    if (cov > 0.001) {
      vec3 p = pMin;
      vec3 n = latNormal(p);
      float rp = length(p);
      vec3 rad = p / max(rp, 1e-4);
      float ndl = dot(n, L);
      float wrap = clamp((ndl + 0.42) / 1.42, 0.0, 1.0);
      float ndv = clamp(dot(n, V), 0.0, 1.0);
      // occlusion: deep in the shell and in tight creases
      float aoDepth = smoothstep(RM - TH * 1.1, RM + TH, rp);
      float aoS = clamp(latSdf(p + n * 0.05) / 0.05, 0.0, 1.0);
      float ao = (0.45 + 0.55 * aoDepth) * (0.6 + 0.4 * aoS);
      // thin edges glow with the light inside (subsurface)
      float edge = 1.0 - clamp((gT - abs(latG(p))) / max(gT, 0.05), 0.0, 1.0);
      float inward = clamp(-dot(n, rad), 0.0, 1.0);
      float side = 1.0 - abs(dot(n, rad));
      vec3 albedo = light ? vec3(0.97, 0.965, 0.985) : vec3(0.93, 0.92, 0.965);
      vec3 sky = mix(vec3(0.42, 0.4, 0.55), vec3(0.95, 0.95, 1.0), 0.5 + 0.5 * n.y);
      vec3 diff = albedo * (vec3(1.0, 0.98, 0.95) * wrap * 0.82 + sky * 0.3) * ao;
      vec3 inLight = innerCol(0.75) * (inward * 0.85 + side * 0.5) * (0.4 + 0.6 * heartI) * (1.0 - aoDepth * 0.55);
      vec3 sss = innerCol(0.6) * pow(edge, 2.2) * (0.22 + 0.25 * heartI + shellPulse * 0.9);
      vec3 rf = reflect(-L, n);
      float sp = pow(max(dot(rf, V), 0.0), 56.0) * 0.55 + pow(max(dot(rf, V), 0.0), 9.0) * 0.06;
      float fres = pow(1.0 - ndv, 3.0);
      vec3 pearl = mix(vec3(1.0, 0.82, 0.95), vec3(0.78, 0.9, 1.0), 0.5 + 0.5 * sin(fres * 5.0 + n.y * 2.5 + n.x * 1.5));
      fc = diff + inLight * (light ? 0.75 : 1.0) + sss + vec3(1.0) * sp * ao + pearl * fres * 0.22 * ao;
