    vec3 rc = mix(vec3(0.5, 0.45, 1.0), vec3(0.2, 0.42, 1.0), smoothstep(1.0, 1.5, rP));
    if (!light) {
      vec3 c = rc * sh * 1.25 + vec3(0.35, 0.4, 1.0) * rimGlow;
