// Relative GPU cost: render each concept solo at a big radius and count frames over 3s.
// usage: node perf.mjs <r> <id> [id...] [--typing]
import { spawn } from "node:child_process";
import { mkdirSync, rmSync } from "node:fs";
const args = process.argv.slice(2);
const R = Number(args[0]);
const typing = args.includes("--typing");
const ids = args.slice(1).filter((a) => !a.startsWith("--"));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const port = 9300 + Math.floor(Math.random() * 300);
const profile = `C:/Users/edmem/AppData/Local/Temp/cyrus-shots/prof-perf-${port}`;
mkdirSync(profile, { recursive: true });
const chrome = spawn("C:/Program Files/Google/Chrome/Application/chrome.exe", [
  "--headless=new", `--remote-debugging-port=${port}`, "--enable-gpu", "--ignore-gpu-blocklist",
  "--window-size=1600,1600", `--user-data-dir=${profile}`, "--disable-gpu-vsync", "--disable-frame-rate-limit", "about:blank",
]);
let targets;
for (let i = 0; i < 60; i++) { await sleep(250); try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); if (targets.some((t) => t.type === "page")) break; } catch {} }
const ws = new WebSocket(targets.find((t) => t.type === "page").webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let id_ = 0; const pending = new Map(); const errors = [];
ws.onmessage = (m) => { const msg = JSON.parse(m.data); if (msg.method === "Runtime.consoleAPICalled" && msg.params.type === "error") errors.push(msg.params.args.map((a) => a.value ?? a.description).join(" ").slice(0, 400)); if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); } };
const send = (method, params = {}) => new Promise((r) => { const i = ++id_; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const evaluate = async (expr) => (await send("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true })).result?.result?.value;
await send("Runtime.enable");
await send("Page.enable");
await send("Page.addScriptToEvaluateOnNewDocument", { source: `
  (() => {
    const orig = WebGLRenderingContext.prototype.drawArrays;
    const px = new Uint8Array(4);

    const px = new Uint8Array(4);
    window.__dt = [];
    WebGLRenderingContext.prototype.drawArrays = function (...a) {
      const t0 = performance.now();
      orig.apply(this, a);
      this.readPixels(0, 0, 1, 1, this.RGBA, this.UNSIGNED_BYTE, px);
      window.__dt.push(performance.now() - t0);
    };
  })();` });
await send("Emulation.setDeviceMetricsOverride", { width: 1600, height: 1600, deviceScaleFactor: 1, mobile: false });
for (const id of ids) {
  await send("Page.navigate", { url: `http://localhost:3000/cores?solo=${id}&r=${R}&mode=idle${typing ? "&typing=1" : ""}` });
  await sleep(3500);
  await evaluate(`window.__dt = []`);
  await sleep(3000);
  const fps = await evaluate(`(()=>{const a=[...window.__dt].sort((x,y)=>x-y);return a.length?a[Math.floor(a.length/2)]:-1})()`);
  const px = await evaluate(`(()=>{const c=document.querySelector('.core-host canvas');return c?c.width+'x'+c.height:null})()`);
  console.log(id.padEnd(10), "canvas", px, "median ms/draw", fps.toFixed(2));
}
console.log("errors:", errors.length ? errors.join("\n") : "none");
ws.close(); chrome.kill(); await sleep(300); try { rmSync(profile, { recursive: true, force: true }); } catch {}
process.exit(0);

