import type { CoreConcept } from "../types";

/**
 * Plasma Storm — a glass plasma globe. Lightning filaments run from the Y (the electrode) to
 * the glass, wandering and flickering, each one pooling into a hot contact spot where it meets
 * the wall; faint electric veins web the glass itself. Every keystroke fires a fresh branching
 * bolt that punches through the glass into the space outside, aimed by the keystroke's seed.
 */
export const storm: CoreConcept = {
  id: "storm",
  name: "Plasma Storm",
  kind: "3D",
  tagline: "Lightning in a glass globe",
  description:
    "A glass plasma globe: violet lightning crawls from the glowing Y out to the wall, pooling in hot contact spots, over a web of electric veins and a soft inner haze. Every keystroke fires a fresh branching bolt that punches through the glass into open space.",
  typing: "Each keystroke fires a bolt out through the glass; typing thickens the storm.",
  extent: 2.05,
  frag: /* glsl */ `
float h1(float n) { return fract(sin(n * 127.1 + 0.37) * 43758.5453); }
float n1s(float x) { float i = floor(x); float f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(h1(i), h1(i + 1.0), f) * 2.0 - 1.0; }
float n1j(float x) { float i = floor(x); float f = fract(x); return mix(h1(i), h1(i + 1.0), f) * 2.0 - 1.0; }
// Lateral offset along a bolt: a smooth wander plus jagged, crawling detail.
float boltDisp(float x, float seed, float t) {
  return n1s(x * 2.1 + seed * 13.1 + t * 0.8) * 0.58
       + n1j(x * 7.3 + seed * 7.7 + t * 2.6) * 0.3
       + n1j(x * 21.0 + seed * 3.3 + t * 6.0) * 0.12;
}
// Distance from P to a lightning path from a to b. pin = 1 pins both ends; 0 leaves the far end free.
vec2 boltDist(vec2 P, vec2 a, vec2 b, float amp, float seed, float t, float pin) {
  vec2 ab = b - a;
  float L = max(length(ab), 1e-4);
  vec2 u = ab / L;
  vec2 ap = P - a;
  float x = dot(ap, u);
  float y = ap.x * u.y - ap.y * u.x;
  float h = clamp(x / L, 0.0, 1.0);
  float env = sin(PI * mix(h * 0.5, h, pin));
  float D = boltDisp(h * L, seed, t) * amp * env;
  float D2 = boltDisp(h * L + 0.01, seed, t) * amp * env;
  float slope = (D2 - D) / 0.01;
  float dx = x - clamp(x, 0.0, L);
  return vec2(length(vec2(dx, (y - D) / sqrt(1.0 + slope * slope))), h);
}
// Point on that path at parameter h (for hanging branches off it).
vec2 boltPoint(vec2 a, vec2 b, float h, float amp, float seed, float t, float pin) {
  vec2 ab = b - a;
  float L = max(length(ab), 1e-4);
  vec2 u = ab / L;
  vec2 v = vec2(u.y, -u.x);
  float env = sin(PI * mix(h * 0.5, h, pin));
  return a + ab * h + v * boltDisp(h * L, seed, t) * amp * env;
}
vec3 inkOf(vec3 c) { return pow(c, vec3(1.4)) * 0.82; }

vec4 core(vec2 uv) {
  float R = uRadius;
  vec2 P = uv / R;
  float rP = length(P);
  float r2 = dot(P, P);
  float pxW = uPx / R;
  float t = uTime;
  float e = uEnergy;
  bool light = uLight > 0.5;
  if (rP > 2.05) return vec4(0.0);
  float jit = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));

  // continuous crackle: sustained typing and forging (which holds energy up) make it nervous
  float crackle = smoothstep(0.12, 0.55, e);
  float wc = max(pxW * 0.75, 0.0035);
  vec3 violet = vec3(0.62, 0.3, 1.0);
  vec3 hot = vec3(1.0, 0.86, 1.0);

  vec3 col = vec3(0.0);
  float a = 0.0;
  vec3 yBase = vec3(0.0);
  float yCov = 0.0;

  // ── inside the globe ──
  if (rP < 1.0 + pxW * 2.0) {
    vec3 n = sphereNormal(P);
    float z = n.z;
    // dark glass interior with a soft inner haze
    col = mix(vec3(0.045, 0.02, 0.1), vec3(0.012, 0.006, 0.03), smoothstep(0.0, 1.0, rP));
    vec3 hq = vec3(P * 1.8, t * 0.12);
    float wisp = fbm2(hq + vec3(fbm2(hq * 0.7 + 3.0) * 1.4, 0.0, uSwirl * 0.2));
    float heart = exp(-r2 * 3.2);
    col += violet * heart * (0.16 + 0.12 * uPulse + e * 0.1) + vec3(0.42, 0.25, 0.95) * wisp * wisp * exp(-r2 * 1.5) * 0.2;

    // electric veins webbing the glass (back wall first, then front)
    vec3 qb = rotY(uSwirl * 0.35) * rotX(0.4) * vec3(P, -z);
    vec3 qf = rotY(uSwirl * 0.35) * rotX(0.4) * vec3(P, z);
    float vb = pow(ridged(qb * 2.3 + vec3(0.0, t * 0.05, 0.0)), 14.0);
    float vf = pow(ridged(qf * 2.3 + vec3(0.0, t * 0.05, 0.0)), 14.0);
    float limb = 0.35 + 0.65 * pow(1.0 - z, 1.5);
    col += mix(violet, vec3(0.55, 0.45, 1.0), 0.3) * vb * limb * (0.22 + e * 0.25 + uPulse * 0.2);

    // the Y — the electrode
    vec3 pB; float sB; float armB;
    float yD = 10.0;
    if (rP < 0.5) yD = yTrace(vec3(P, 3.0), vec3(0.0, 0.0, -1.0), 6.0, 0.64, pB, sB, armB);
    yCov = yCoverage(yD, pxW);
    vec3 yC = vec3(0.0);
    float yGlow = 0.0;
    if (yD < 0.1) {
      yBase = yColor(pB.xy, armB);
      if (yD < 0.01) yC = yShade(pB, armB, vec3(0.0, 0.0, -1.0), 1.25 + uPulse * 0.6 + e * 0.35 + uKick * 0.6);
      yGlow = exp(-max(yD, 0.0) * 22.0) * (1.0 - yCov);
    }

    // filaments: electrode -> glass, wandering, flickering; more and brighter with typing
    vec3 fil = vec3(0.0);
    float nFil = 7.0 + 7.0 * e + uPulse * 2.0;
    for (int i = 0; i < 16; i++) {
      float fi = float(i);
      float wgt = clamp(nFil - fi, 0.0, 1.0);
      if (wgt <= 0.0) break;
      float th = fi * 2.39996 + 0.6 * n1s(t * 0.13 + fi * 3.7) + uSwirl * 0.35;
      float el = 0.62 * n1s(t * 0.11 + fi * 5.3 + 10.0);
      vec3 d = vec3(cos(th) * cos(el), sin(th) * cos(el), sin(el));
      vec2 e2 = d.xy * 0.985;
      // cheap reject: far from this filament's corridor
      vec2 ab = e2;
      float hh = clamp(dot(P, ab) / max(dot(ab, ab), 1e-4), 0.0, 1.0);
      float dc = length(P - ab * hh);
      vec2 dpE = P - e2;
      float dE2 = dot(dpE, dpE);
      if (dc > 0.3 && dE2 > 0.09) continue;
      float flick = 0.62 + 0.38 * n1s(t * (7.0 + crackle * 10.0) + fi * 7.1);
      float depth = mix(0.38, 1.0, smoothstep(-0.7, 0.7, d.z));
      vec2 bd = boltDist(P, vec2(0.0), e2, 0.12, fi * 1.618, t * (1.0 + crackle * 1.5), 1.0);
      float dd = bd.x;
      vec3 gc = mix(violet, palette(clamp(e2.x * 1.1, -1.0, 1.0)), 0.4);
      float w = wc * mix(0.8, 1.3, depth);
      float coreL = exp(-dd * dd / (w * w)) * smoothstep(0.06, 0.2, bd.y);
      float q = 0.0009 * depth;
      float glow = q / (dd * dd + q) * (1.0 - smoothstep(0.15, 0.3, dd));
      // the strike pools into a hot spot on the glass, with a few short fingers
      float spot = exp(-dE2 / (0.0012 + depth * 0.001)) + 0.35 * exp(-dE2 / 0.01);
      float br = wgt * flick * depth * (0.85 + e * 0.5 + uPulse * 0.4);
      fil += (hot * coreL * 1.15 + gc * glow * 0.75 + mix(gc, hot, 0.5) * spot * 0.9) * br;
    }

    // keystroke bolts: the inner part of each strike (the outside part is drawn below)
    // (shared code would be nicer, but WebGL1 inlining keeps this cheaper)
    vec3 strikeIn = vec3(0.0);
    for (int k = 0; k < 4; k++) {
      float s = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
      float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
      float sd = k == 0 ? uWaveSeed.x : k == 1 ? uWaveSeed.y : k == 2 ? uWaveSeed.z : uWaveSeed.w;
      if (s <= 0.0 || ag > 0.6) continue;
      float an = sd * TAU;
      vec2 dir = vec2(cos(an), sin(an));
      float Lb = mix(0.25, 1.68, smoothstep(0.0, 0.07, ag));
      float fade = exp(-ag * 6.0) * (1.0 + 2.0 * exp(-ag * 30.0));
      vec2 bd = boltDist(P, vec2(0.0), dir * Lb, 0.2, sd * 91.0, 0.0, 0.0);
      float cl = exp(-bd.x * bd.x / (wc * wc * 2.2)) * smoothstep(0.04, 0.12, bd.y * Lb);
      float q = 0.0016;
      float gl = q / (bd.x * bd.x + q);
      strikeIn += (hot * cl * 1.6 + mix(violet, vec3(1.0, 0.4, 0.9), 0.4) * gl * 0.8) * fade;
    }

    // compose: haze & back veins, filaments, the Y and its corona, front veins, strikes, glass
    float behindY = 1.0 - yCov;
    col += fil * behindY;
    col += mix(yBase, vec3(0.85, 0.6, 1.0), 0.35) * yGlow * (0.75 + 0.35 * n1s(t * 9.0) * crackle + uPulse * 0.6 + uKick * 0.8);
    col = mix(col, yC, yCov);
    col += mix(violet, vec3(0.75, 0.6, 1.0), 0.4) * vf * limb * (0.3 + e * 0.35 + uPulse * 0.25);
    col += strikeIn * (1.0 - yCov * 0.85);

    // glass: fresnel rim, window reflection, a sharp glint
    float fres = pow(1.0 - z, 4.0);
    vec3 refl = reflect(vec3(0.0, 0.0, -1.0), n);
    float band = smoothstep(0.5, 0.88, refl.y) * smoothstep(-0.45, 0.05, refl.x) * smoothstep(0.75, 0.25, refl.x);
    vec3 Lg = normalize(vec3(-0.62, 0.72, 0.45));
    float glint = pow(max(dot(reflect(-Lg, n), vec3(0.0, 0.0, 1.0)), 0.0), 600.0);
    vec3 rimC = mix(vec3(0.55, 0.35, 1.0), palette(clamp(P.x, -1.0, 1.0)), 0.5);
    col += rimC * fres * (0.75 + uPulse * 0.4 + e * 0.3) + vec3(0.8, 0.82, 1.0) * band * 0.1 + vec3(1.0) * glint * 1.2;
    col = tonemap(col);
    float edgeDark = exp(-pow((rP - 0.965) / 0.012, 2.0));
    col *= 1.0 - edgeDark * 0.5;
    col = mix(col, mix(rimC, vec3(1.0), 0.45), smoothstep(0.978, 0.996, rP) * 0.9);
    a = 1.0 - smoothstep(1.0 - pxW, 1.0 + pxW, rP);
    col *= a;
  }

  // ── outside the globe: bloom and the strikes punching out into space ──
  if (rP > 1.0 - pxW) {
    float dOut = max(rP - 1.0, 0.0);
    vec3 c = vec3(0.0);
    float bloom = exp(-dOut * 30.0) * 0.55 + exp(-dOut * 7.0) * (0.08 + e * 0.12 + uPulse * 0.12);
    c += mix(violet, palette(clamp(P.x / max(rP, 1e-4), -1.0, 1.0)), 0.35) * bloom;
    vec3 strike = vec3(0.0);
    float strikeA = 0.0;
    for (int k = 0; k < 4; k++) {
      float s = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
      float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
      float sd = k == 0 ? uWaveSeed.x : k == 1 ? uWaveSeed.y : k == 2 ? uWaveSeed.z : uWaveSeed.w;
      if (s <= 0.0 || ag > 0.6) continue;
      float an = sd * TAU;
      vec2 dir = vec2(cos(an), sin(an));
      // only bother near this strike's sector
      if (dot(P, dir) < 0.6) continue;
      float Lb = mix(0.25, 1.68, smoothstep(0.0, 0.07, ag));
      float fade = exp(-ag * 6.0) * (1.0 + 2.0 * exp(-ag * 30.0));
      vec2 bd = boltDist(P, vec2(0.0), dir * Lb, 0.2, sd * 91.0, 0.0, 0.0);
      float cl = exp(-bd.x * bd.x / (wc * wc * 2.2));
      float q = 0.0016;
      float gl = q / (bd.x * bd.x + q);
      float glA = cl + gl * 0.6;
      // branches forking off the outer half
      for (int b = 0; b < 3; b++) {
        float fb = float(b);
        float hb = 0.42 + 0.17 * fb + 0.08 * h1(sd * 17.0 + fb);
        vec2 p0 = boltPoint(vec2(0.0), dir * Lb, hb, 0.2, sd * 91.0, 0.0, 0.0);
        float ba = an + (h1(sd * 31.0 + fb * 3.0) < 0.5 ? -1.0 : 1.0) * (0.35 + 0.4 * h1(sd * 7.0 + fb));
        float bl = (0.22 + 0.25 * h1(sd * 11.0 + fb)) * (1.0 - hb * 0.4) * smoothstep(0.0, 0.1, ag);
        vec2 bd2 = boltDist(P, p0, p0 + vec2(cos(ba), sin(ba)) * bl, 0.12, sd * 53.0 + fb * 9.0, 0.0, 0.0);
        float cl2 = exp(-bd2.x * bd2.x / (wc * wc * 1.2)) * (1.0 - bd2.y * 0.6);
        float gl2 = 0.0007 / (bd2.x * bd2.x + 0.0007);
        cl = max(cl, cl2 * 0.8);
        gl += gl2 * 0.5;
        glA += cl2 * 0.8 + gl2 * 0.3;
      }
      // a flash where it bursts through the glass, and at its tip
      vec2 exitP = boltPoint(vec2(0.0), dir * Lb, 1.0 / Lb, 0.2, sd * 91.0, 0.0, 0.0);
      vec2 dx = P - exitP;
      float flash = exp(-dot(dx, dx) / 0.006) * exp(-ag * 9.0);
      vec3 sc = hot * cl * 1.6 + mix(violet, vec3(1.0, 0.4, 0.9), 0.4) * gl * 0.85 + hot * flash * 1.2;
      strike += sc * fade;
      strikeA += (glA + flash) * fade;
    }
    vec3 cc = c + strike;
    float ca = clamp(max(max(cc.r, cc.g), cc.b), 0.0, 1.0);
    float outer = 1.0 - smoothstep(1.78, 2.02, rP);
    if (!light) {
      cc = tonemap(cc) * outer;
      ca *= outer;
      col += min(cc, vec3(ca)) * (1.0 - a);
      a += ca * (1.0 - a);
    } else {
      // on paper: lightning as violet ink with a pale halo, the bloom as a faint tint
      float inkA = clamp(strikeA, 0.0, 1.0) * outer;
      float tintA = clamp(bloom * 0.35, 0.0, 1.0) * outer;
      vec3 ink = mix(vec3(0.42, 0.12, 0.85), vec3(0.75, 0.15, 0.7), 0.3);
      vec3 lc = ink * tintA;
      float la = tintA;
      lc = lc * (1.0 - inkA) + ink * inkA;
      la = la * (1.0 - inkA) + inkA;
      col += lc * (1.0 - a);
      a += la * (1.0 - a);
    }
  }

  a = clamp(a, 0.0, 1.0);
  col = min(max(col, 0.0), vec3(a));
  col += (jit - 0.5) / 255.0 * a;
  return vec4(max(col, 0.0), a);
}
`,
};

toolu_019chottikCb1Sk6xbzhrLaj.content:
import type { CoreConcept } from "../types";

/**
 * Plasma Storm — a glass plasma globe. Lightning filaments run from the Y (the electrode) to
 * the glass, wandering and flickering, each one pooling into a hot contact spot where it meets
 * the wall; faint electric veins web the glass itself. Every keystroke fires a fresh branching
 * bolt that punches through the glass into the space outside, aimed by the keystroke's seed.
 */
export const storm: CoreConcept = {
  id: "storm",
  name: "Plasma Storm",
  kind: "3D",
  tagline: "Lightning in a glass globe",
  description:
    "A glass plasma globe: violet lightning crawls from the glowing Y out to the wall, pooling in hot contact spots, over a web of electric veins and a soft inner haze. Every keystroke fires a fresh branching bolt that punches through the glass into open space.",
  typing: "Each keystroke fires a bolt out through the glass; typing thickens the storm.",
  extent: 2.05,
  frag: /* glsl */ `
float h1(float n) { return fract(sin(n * 127.1 + 0.37) * 43758.5453); }
float n1s(float x) { float i = floor(x); float f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(h1(i), h1(i + 1.0), f) * 2.0 - 1.0; }
float n1j(float x) { float i = floor(x); float f = fract(x); return mix(h1(i), h1(i + 1.0), f) * 2.0 - 1.0; }
// Lateral offset along a bolt: a smooth wander plus jagged, crawling detail.
float boltDisp(float x, float seed, float t) {
  return n1s(x * 2.1 + seed * 13.1 + t * 0.8) * 0.58
       + n1j(x * 7.3 + seed * 7.7 + t * 2.6) * 0.3
       + n1j(x * 21.0 + seed * 3.3 + t * 6.0) * 0.12;
}
// Distance from P to a lightning path from a to b. pin = 1 pins both ends; 0 leaves the far end free.
vec2 boltDist(vec2 P, vec2 a, vec2 b, float amp, float seed, float t, float pin) {
  vec2 ab = b - a;
  float L = max(length(ab), 1e-4);
  vec2 u = ab / L;
  vec2 ap = P - a;
  float x = dot(ap, u);
  float y = ap.x * u.y - ap.y * u.x;
  float h = clamp(x / L, 0.0, 1.0);
  float env = sin(PI * mix(h * 0.5, h, pin));
  float D = boltDisp(h * L, seed, t) * amp * env;
  float D2 = boltDisp(h * L + 0.01, seed, t) * amp * env;
  float slope = (D2 - D) / 0.01;
  float dx = x - clamp(x, 0.0, L);
  return vec2(length(vec2(dx, (y - D) / sqrt(1.0 + slope * slope))), h);
}
// Point on that path at parameter h (for hanging branches off it).
vec2 boltPoint(vec2 a, vec2 b, float h, float amp, float seed, float t, float pin) {
  vec2 ab = b - a;
  float L = max(length(ab), 1e-4);
  vec2 u = ab / L;
  vec2 v = vec2(u.y, -u.x);
  float env = sin(PI * mix(h * 0.5, h, pin));
  return a + ab * h + v * boltDisp(h * L, seed, t) * amp * env;
}
vec3 inkOf(vec3 c) { return pow(c, vec3(1.4)) * 0.82; }

vec4 core(vec2 uv) {
  float R = uRadius;
  vec2 P = uv / R;
  float rP = length(P);
  float r2 = dot(P, P);
  float pxW = uPx / R;
  float t = uTime;
  float e = uEnergy;
  bool light = uLight > 0.5;
  if (rP > 2.05) return vec4(0.0);
  float jit = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));

  // continuous crackle: sustained typing and forging (which holds energy up) make it nervous
  float crackle = smoothstep(0.12, 0.55, e);
  float wc = max(pxW * 0.75, 0.0035);
  vec3 violet = vec3(0.62, 0.3, 1.0);
  vec3 hot = vec3(1.0, 0.86, 1.0);

  vec3 col = vec3(0.0);
  float a = 0.0;
  vec3 yBase = vec3(0.0);
  float yCov = 0.0;

  // ── inside the globe ──
  if (rP < 1.0 + pxW * 2.0) {
    vec3 n = sphereNormal(P);
    float z = n.z;
    // dark glass interior with a soft inner haze
    col = mix(vec3(0.045, 0.02, 0.1), vec3(0.012, 0.006, 0.03), smoothstep(0.0, 1.0, rP));
    vec3 hq = vec3(P * 1.8, t * 0.12);
    float wisp = fbm2(hq + vec3(fbm2(hq * 0.7 + 3.0) * 1.4, 0.0, uSwirl * 0.2));
    float heart = exp(-r2 * 3.2);
    col += violet * heart * (0.16 + 0.12 * uPulse + e * 0.1) + vec3(0.42, 0.25, 0.95) * wisp * wisp * exp(-r2 * 1.5) * 0.2;

    // electric veins webbing the glass (back wall first, then front)
    vec3 qb = rotY(uSwirl * 0.35) * rotX(0.4) * vec3(P, -z);
    vec3 qf = rotY(uSwirl * 0.35) * rotX(0.4) * vec3(P, z);
    float vb = pow(ridged(qb * 2.3 + vec3(0.0, t * 0.05, 0.0)), 14.0);
    float vf = pow(ridged(qf * 2.3 + vec3(0.0, t * 0.05, 0.0)), 14.0);
    float limb = 0.35 + 0.65 * pow(1.0 - z, 1.5);
    col += mix(violet, vec3(0.55, 0.45, 1.0), 0.3) * vb * limb * (0.22 + e * 0.25 + uPulse * 0.2);

    // the Y — the electrode
    vec3 pB; float sB; float armB;
    float yD = 10.0;
    if (rP < 0.5) yD = yTrace(vec3(P, 3.0), vec3(0.0, 0.0, -1.0), 6.0, 0.64, pB, sB, armB);
    yCov = yCoverage(yD, pxW);
    vec3 yC = vec3(0.0);
    float yGlow = 0.0;
    if (yD < 0.1) {
      yBase = yColor(pB.xy, armB);
      if (yD < 0.01) yC = yShade(pB, armB, vec3(0.0, 0.0, -1.0), 1.25 + uPulse * 0.6 + e * 0.35 + uKick * 0.6);
      yGlow = exp(-max(yD, 0.0) * 22.0) * (1.0 - yCov);
    }

    // filaments: electrode -> glass, wandering, flickering; more and brighter with typing
    vec3 fil = vec3(0.0);
    float nFil = 7.0 + 7.0 * e + uPulse * 2.0;
    for (int i = 0; i < 16; i++) {
      float fi = float(i);
      float wgt = clamp(nFil - fi, 0.0, 1.0);
      if (wgt <= 0.0) break;
      float th = fi * 2.39996 + 0.6 * n1s(t * 0.13 + fi * 3.7) + uSwirl * 0.35;
      float el = 0.62 * n1s(t * 0.11 + fi * 5.3 + 10.0);
      vec3 d = vec3(cos(th) * cos(el), sin(th) * cos(el), sin(el));
      vec2 e2 = d.xy * 0.985;
      // cheap reject: far from this filament's corridor
      vec2 ab = e2;
      float hh = clamp(dot(P, ab) / max(dot(ab, ab), 1e-4), 0.0, 1.0);
      float dc = length(P - ab * hh);
      vec2 dpE = P - e2;
      float dE2 = dot(dpE, dpE);
      if (dc > 0.3 && dE2 > 0.09) continue;
      float flick = 0.62 + 0.38 * n1s(t * (7.0 + crackle * 10.0) + fi * 7.1);
      float depth = mix(0.38, 1.0, smoothstep(-0.7, 0.7, d.z));
      vec2 bd = boltDist(P, vec2(0.0), e2, 0.12, fi * 1.618, t * (1.0 + crackle * 1.5), 1.0);
      float dd = bd.x;
      vec3 gc = mix(violet, palette(clamp(e2.x * 1.1, -1.0, 1.0)), 0.4);
      float w = wc * mix(0.8, 1.3, depth);
      float coreL = exp(-dd * dd / (w * w)) * smoothstep(0.06, 0.2, bd.y);
      float q = 0.0009 * depth;
      float glow = q / (dd * dd + q) * (1.0 - smoothstep(0.15, 0.3, dd));
      // the strike pools into a hot spot on the glass, with a few short fingers
      float spot = exp(-dE2 / (0.0012 + depth * 0.001)) + 0.35 * exp(-dE2 / 0.01);
      float br = wgt * flick * depth * (0.85 + e * 0.5 + uPulse * 0.4);
      fil += (hot * coreL * 1.15 + gc * glow * 0.75 + mix(gc, hot, 0.5) * spot * 0.9) * br;
    }

    // keystroke bolts: the inner part of each strike (the outside part is drawn below)
    // (shared code would be nicer, but WebGL1 inlining keeps this cheaper)
    vec3 strikeIn = vec3(0.0);
    for (int k = 0; k < 4; k++) {
      float s = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
      float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
      float sd = k == 0 ? uWaveSeed.x : k == 1 ? uWaveSeed.y : k == 2 ? uWaveSeed.z : uWaveSeed.w;
      if (s <= 0.0 || ag > 0.6) continue;
      float an = sd * TAU;
      vec2 dir = vec2(cos(an), sin(an));
      float Lb = mix(0.25, 1.68, smoothstep(0.0, 0.07, ag));
      float fade = exp(-ag * 6.0) * (1.0 + 2.0 * exp(-ag * 30.0));
      vec2 bd = boltDist(P, vec2(0.0), dir * Lb, 0.2, sd * 91.0, 0.0, 0.0);
      float cl = exp(-bd.x * bd.x / (wc * wc * 2.2)) * smoothstep(0.04, 0.12, bd.y * Lb);
      float q = 0.0016;
      float gl = q / (bd.x * bd.x + q);
      strikeIn += (hot * cl * 1.6 + mix(violet, vec3(1.0, 0.4, 0.9), 0.4) * gl * 0.8) * fade;
    }

    // compose: haze & back veins, filaments, the Y and its corona, front veins, strikes, glass
    float behindY = 1.0 - yCov;
    col += fil * behindY;
    col += mix(yBase, vec3(0.85, 0.6, 1.0), 0.35) * yGlow * (0.75 + 0.35 * n1s(t * 9.0) * crackle + uPulse * 0.6 + uKick * 0.8);
    col = mix(col, yC, yCov);
    col += mix(violet, vec3(0.75, 0.6, 1.0), 0.4) * vf * limb * (0.3 + e * 0.35 + uPulse * 0.25);
    col += strikeIn * (1.0 - yCov * 0.85);

    // glass: fresnel rim, window reflection, a sharp glint
    float fres = pow(1.0 - z, 4.0);
    vec3 refl = reflect(vec3(0.0, 0.0, -1.0), n);
    float band = smoothstep(0.5, 0.88, refl.y) * smoothstep(-0.45, 0.05, refl.x) * smoothstep(0.75, 0.25, refl.x);
    vec3 Lg = normalize(vec3(-0.62, 0.72, 0.45));
    float glint = pow(max(dot(reflect(-Lg, n), vec3(0.0, 0.0, 1.0)), 0.0), 600.0);
    vec3 rimC = mix(vec3(0.55, 0.35, 1.0), palette(clamp(P.x, -1.0, 1.0)), 0.5);
    col += rimC * fres * (0.75 + uPulse * 0.4 + e * 0.3) + vec3(0.8, 0.82, 1.0) * band * 0.1 + vec3(1.0) * glint * 1.2;
    col = tonemap(col);
    float edgeDark = exp(-pow((rP - 0.965) / 0.012, 2.0));
    col *= 1.0 - edgeDark * 0.5;
    col = mix(col, mix(rimC, vec3(1.0), 0.45), smoothstep(0.978, 0.996, rP) * 0.9);
    a = 1.0 - smoothstep(1.0 - pxW, 1.0 + pxW, rP);
    col *= a;
  }

  // ── outside the globe: bloom and the strikes punching out into space ──
  if (rP > 1.0 - pxW) {
    float dOut = max(rP - 1.0, 0.0);
    vec3 c = vec3(0.0);
    float bloom = exp(-dOut * 30.0) * 0.55 + exp(-dOut * 7.0) * (0.08 + e * 0.12 + uPulse * 0.12);
    c += mix(violet, palette(clamp(P.x / max(rP, 1e-4), -1.0, 1.0)), 0.35) * bloom;
    vec3 strike = vec3(0.0);
    float strikeA = 0.0;
    for (int k = 0; k < 4; k++) {
      float s = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
      float ag = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
      float sd = k == 0 ? uWaveSeed.x : k == 1 ? uWaveSeed.y : k == 2 ? uWaveSeed.z : uWaveSeed.w;
      if (s <= 0.0 || ag > 0.6) continue;
      float an = sd * TAU;
      vec2 dir = vec2(cos(an), sin(an));
      // only bother near this strike's sector
      if (dot(P, dir) < 0.6) continue;
      float Lb = mix(0.25, 1.68, smoothstep(0.0, 0.07, ag));
      float fade = exp(-ag * 6.0) * (1.0 + 2.0 * exp(-ag * 30.0));
      vec2 bd = boltDist(P, vec2(0.0), dir * Lb, 0.2, sd * 91.0, 0.0, 0.0);
      float cl = exp(-bd.x * bd.x / (wc * wc * 2.2));
      float q = 0.0016;
      float gl = q / (bd.x * bd.x + q);
      float glA = cl + gl * 0.6;
      // branches forking off the outer half
      for (int b = 0; b < 3; b++) {
        float fb = float(b);
        float hb = 0.42 + 0.17 * fb + 0.08 * h1(sd * 17.0 + fb);
        vec2 p0 = boltPoint(vec2(0.0), dir * Lb, hb, 0.2, sd * 91.0, 0.0, 0.0);
        float ba = an + (h1(sd * 31.0 + fb * 3.0) < 0.5 ? -1.0 : 1.0) * (0.35 + 0.4 * h1(sd * 7.0 + fb));
        float bl = (0.22 + 0.25 * h1(sd * 11.0 + fb)) * (1.0 - hb * 0.4) * smoothstep(0.0, 0.1, ag);
        vec2 bd2 = boltDist(P, p0, p0 + vec2(cos(ba), sin(ba)) * bl, 0.12, sd * 53.0 + fb * 9.0, 0.0, 0.0);
        float cl2 = exp(-bd2.x * bd2.x / (wc * wc * 1.2)) * (1.0 - bd2.y * 0.6);
        float gl2 = 0.0007 / (bd2.x * bd2.x + 0.0007);
        cl = max(cl, cl2 * 0.8);
        gl += gl2 * 0.5;
        glA += cl2 * 0.8 + gl2 * 0.3;
      }
      // a flash where it bursts through the glass, and at its tip
      vec2 exitP = boltPoint(vec2(0.0), dir * Lb, 1.0 / Lb, 0.2, sd * 91.0, 0.0, 0.0);
      vec2 dx = P - exitP;
      float flash = exp(-dot(dx, dx) / 0.006) * exp(-ag * 9.0);
      vec3 sc = hot * cl * 1.6 + mix(violet, vec3(1.0, 0.4, 0.9), 0.4) * gl * 0.85 + hot * flash * 1.2;
      strike += sc * fade;
      strikeA += (glA + flash) * fade;
    }
    vec3 cc = c + strike;
    float ca = clamp(max(max(cc.r, cc.g), cc.b), 0.0, 1.0);
    float outer = 1.0 - smoothstep(1.78, 2.02, rP);
    if (!light) {
      cc = tonemap(cc) * outer;
      ca *= outer;
      col += min(cc, vec3(ca)) * (1.0 - a);
      a += ca * (1.0 - a);
    } else {
      // on paper: lightning as violet ink with a pale halo, the bloom as a faint tint
      float inkA = clamp(strikeA, 0.0, 1.0) * outer;
      float tintA = clamp(bloom * 0.35, 0.0, 1.0) * outer;
      vec3 ink = mix(vec3(0.42, 0.12, 0.85), vec3(0.75, 0.15, 0.7), 0.3);
      vec3 lc = ink * tintA;
      float la = tintA;
      lc = lc * (1.0 - inkA) + ink * inkA;
      la = la * (1.0 - inkA) + inkA;
      col += lc * (1.0 - a);
      a += la * (1.0 - a);
    }
  }

  a = clamp(a, 0.0, 1.0);
  col = min(max(col, 0.0), vec3(a));
  col += (jit - 0.5) / 255.0 * a;
  return vec4(max(col, 0.0), a);
}
`,
};

